package com.example.ayaneooverlay

/**
 * Content of the in-app help guide: one topic per feature, in every UI language
 * (en, ru, nl, es, de, fr, it, zh). Generated from a single source so all languages
 * stay in step. English is the fallback.
 */
object HelpContent {
    class Entry(val title: String, val summary: String, val bullets: List<String>)
    class Topic(val id: String, val icon: String, private val entries: Map<String, Entry>) {
        fun entry(language: String): Entry = entries[language] ?: entries.getValue("en")
    }

    val topics: List<Topic> = listOf(
        Topic("home", "star", mapOf(
            "en" to Entry("Home screen & pages", "Five pages: swipe, or press LB / RB on the controller.", listOf("Page 1 — dashboard: profiles, FPS, fan, display, CPU, GPU, battery, memory and storage. Tap a card to open its controls.", "Page 2 — more controls: Keyboard, Touchpad, PC keyboard, Profiles, Controller, Equalizer and Device.", "Page 3 — Favorites, page 4 — Game tuning, page 5 — Quick settings. The dots at the bottom show where you are.", "The bottom bar of the dashboard has Brightness, Sound, Dual screen, Capture and Settings.", "Every theme shows FPS as a line chart of the last minute. CPU and GPU temperatures turn yellow from 65 °C and red from 85 °C; the battery card estimates time left or time to full within seconds.")),
            "ru" to Entry("Главный экран и страницы", "Пять страниц: листай пальцем или кнопками LB / RB.", listOf("Страница 1 — панель: профили, FPS, вентилятор, экран, CPU, GPU, батарея, память и накопитель. Нажми на карточку, чтобы открыть её настройки.", "Страница 2 — дополнительное управление: клавиатура, тачпад, PC-клавиатура, профили, контроллер, эквалайзер и устройство.", "Страница 3 — избранное, страница 4 — тюнинг игр, страница 5 — быстрые настройки. Точки внизу показывают, где ты находишься.", "Внизу панели — кнопки «Яркость», «Звук», «Два экрана», «Снимок» и «Настройки».", "Во всех темах FPS показан графиком за последнюю минуту. Температура CPU и GPU жёлтая с 65 °C и красная с 85 °C; карточка батареи за несколько секунд показывает примерное время работы или до полной зарядки.")),
            "nl" to Entry("Startscherm en pagina's", "Vijf pagina's: veeg, of druk op LB / RB op de controller.", listOf("Pagina 1 — dashboard: profielen, FPS, ventilator, scherm, CPU, GPU, batterij, geheugen en opslag. Tik op een kaart voor de bediening.", "Pagina 2 — meer bediening: toetsenbord, touchpad, pc-toetsenbord, profielen, controller, equalizer en apparaat.", "Pagina 3 — favorieten, pagina 4 — game-afstemming, pagina 5 — snelle instellingen. De stippen onderaan tonen waar je bent.", "De onderste balk van het dashboard heeft Helderheid, Geluid, 2 schermen, Foto en Instellingen.", "Elk thema toont FPS als grafiek van de laatste minuut. CPU- en GPU-temperatuur worden geel vanaf 65 °C en rood vanaf 85 °C; de batterijkaart schat binnen seconden de rest- of oplaadtijd.")),
            "es" to Entry("Pantalla principal y páginas", "Cinco páginas: desliza o pulsa LB / RB en el mando.", listOf("Página 1 — panel: perfiles, FPS, ventilador, pantalla, CPU, GPU, batería, memoria y almacenamiento. Toca una tarjeta para ver sus controles.", "Página 2 — más controles: teclado, panel táctil, teclado de PC, perfiles, mando, ecualizador y dispositivo.", "Página 3 — favoritos, página 4 — ajuste de juegos, página 5 — ajustes rápidos. Los puntos de abajo indican dónde estás.", "La barra inferior del panel tiene Brillo, Sonido, 2 pantallas, Foto y Ajustes.", "Todos los temas muestran los FPS como gráfico del último minuto. La temperatura de CPU y GPU se pone amarilla desde 65 °C y roja desde 85 °C; la tarjeta de batería estima en segundos el tiempo restante o de carga.")),
            "de" to Entry("Startbildschirm und Seiten", "Fünf Seiten: wischen oder LB / RB am Controller drücken.", listOf("Seite 1 — Dashboard: Profile, FPS, Lüfter, Display, CPU, GPU, Akku, Speicher und Laufwerk. Tippe auf eine Karte für ihre Steuerung.", "Seite 2 — weitere Steuerung: Tastatur, Touchpad, PC-Tastatur, Profile, Controller, Equalizer und Gerät.", "Seite 3 — Favoriten, Seite 4 — Spiel-Tuning, Seite 5 — Schnelleinstellungen. Die Punkte unten zeigen die aktuelle Seite.", "Die untere Leiste des Dashboards hat Helligkeit, Ton, Zwei Bildschirme, Foto und Einstellungen.", "Jedes Design zeigt FPS als Diagramm der letzten Minute. CPU- und GPU-Temperatur werden ab 65 °C gelb und ab 85 °C rot; die Akkukarte schätzt nach Sekunden Restlaufzeit oder Ladezeit.")),
            "fr" to Entry("Écran principal et pages", "Cinq pages : balayez ou appuyez sur LB / RB de la manette.", listOf("Page 1 — tableau : profils, FPS, ventilateur, écran, CPU, GPU, batterie, mémoire et stockage. Touchez une carte pour ses réglages.", "Page 2 — autres commandes : clavier, pavé tactile, clavier PC, profils, manette, égaliseur et appareil.", "Page 3 — favoris, page 4 — réglage des jeux, page 5 — réglages rapides. Les points en bas indiquent la page.", "La barre du bas du tableau contient Luminosité, Son, Deux écrans, Capture et Réglages.", "Chaque thème affiche les FPS en graphique sur la dernière minute. Les températures CPU et GPU passent au jaune dès 65 °C et au rouge dès 85 °C ; la carte batterie estime en quelques secondes l’autonomie ou le temps de charge.")),
            "it" to Entry("Schermata principale e pagine", "Cinque pagine: scorri o premi LB / RB sul controller.", listOf("Pagina 1 — pannello: profili, FPS, ventola, schermo, CPU, GPU, batteria, memoria e archiviazione. Tocca una scheda per i suoi controlli.", "Pagina 2 — altri controlli: tastiera, touchpad, tastiera PC, profili, controller, equalizzatore e dispositivo.", "Pagina 3 — preferiti, pagina 4 — ottimizzazione giochi, pagina 5 — impostazioni rapide. I punti in basso indicano la pagina.", "La barra in basso del pannello ha Luminosità, Audio, Due schermi, Foto e Impostazioni.", "Ogni tema mostra gli FPS come grafico dell’ultimo minuto. Le temperature di CPU e GPU diventano gialle da 65 °C e rosse da 85 °C; la scheda batteria stima in pochi secondi l’autonomia o il tempo di ricarica.")),
            "zh" to Entry("主屏幕与页面", "共五页：滑动切换，或按手柄 LB / RB。", listOf("第 1 页 — 仪表盘：配置、FPS、风扇、屏幕、CPU、GPU、电池、内存和存储。点击卡片打开其设置。", "第 2 页 — 更多控制：键盘、触控板、PC 键盘、配置、手柄、均衡器和设备。", "第 3 页 — 收藏，第 4 页 — 游戏调校，第 5 页 — 快捷设置。底部圆点显示当前页。", "仪表盘底栏有亮度、声音、双屏、截图和设置。", "所有主题都以最近一分钟的曲线显示 FPS。CPU 和 GPU 温度 65 °C 起变黄、85 °C 起变红；电池卡片几秒内即可估算剩余时间或充满时间。"))
        )),
        Topic("profiles", "profiles", mapOf(
            "en" to Entry("Performance profiles", "Eco, Balanced, Streaming, Gaming and Max.", listOf("Pick a profile on the dashboard. It sets CPU limits per cluster, GPU frequency and the default fan mode.", "Page 2 → Profiles opens the editor: scheduling mode, fan, CPU cluster limits, GPU limit, GPU lock and Turbo.", "Default fans: Eco off, Balanced and Streaming low, Gaming high, Max full speed. “Reset” restores the defaults.", "After a reboot the last profile comes back, together with a fan mode you chose manually.")),
            "ru" to Entry("Профили производительности", "Eco, Balanced, Streaming, Gaming и Max.", listOf("Выбери профиль на главной. Он задаёт пределы CPU по кластерам, частоту GPU и режим вентилятора по умолчанию.", "Страница 2 → «Профили» открывает редактор: режим планирования, вентилятор, пределы кластеров CPU, предел и фиксация GPU, Турбо.", "Вентилятор по умолчанию: Eco — выкл., Balanced и Streaming — низкий, Gaming — высокий, Max — максимум. «Сбросить» возвращает эти значения.", "После перезагрузки возвращается последний профиль вместе с вручную выбранным режимом вентилятора.")),
            "nl" to Entry("Prestatieprofielen", "Eco, Balanced, Streaming, Gaming en Max.", listOf("Kies een profiel op het dashboard. Het stelt CPU-limieten per cluster, GPU-frequentie en de standaardventilator in.", "Pagina 2 → Profielen opent de editor: planning, ventilator, CPU-clusterlimieten, GPU-limiet, GPU-vergrendeling en Turbo.", "Standaard ventilator: Eco uit, Balanced en Streaming laag, Gaming hoog, Max maximaal. “Herstellen” zet dit terug.", "Na een herstart komt het laatste profiel terug, met een handmatig gekozen ventilatormodus.")),
            "es" to Entry("Perfiles de rendimiento", "Eco, Balanced, Streaming, Gaming y Max.", listOf("Elige un perfil en el panel. Fija límites de CPU por grupo, frecuencia de GPU y el modo de ventilador predeterminado.", "Página 2 → Perfiles abre el editor: planificación, ventilador, límites de CPU, límite y bloqueo de GPU y Turbo.", "Ventilador por defecto: Eco apagado, Balanced y Streaming bajo, Gaming alto, Max máximo. “Restablecer” recupera estos valores.", "Tras reiniciar vuelve el último perfil, junto con el modo de ventilador elegido a mano.")),
            "de" to Entry("Leistungsprofile", "Eco, Balanced, Streaming, Gaming und Max.", listOf("Wähle ein Profil im Dashboard. Es setzt CPU-Grenzen pro Cluster, GPU-Takt und den Standard-Lüftermodus.", "Seite 2 → Profile öffnet den Editor: Planungsmodus, Lüfter, CPU-Cluster, GPU-Grenze, GPU-Sperre und Turbo.", "Standard-Lüfter: Eco aus, Balanced und Streaming niedrig, Gaming hoch, Max maximal. „Zurücksetzen“ stellt sie wieder her.", "Nach einem Neustart kehrt das letzte Profil zurück, samt manuell gewähltem Lüftermodus.")),
            "fr" to Entry("Profils de performance", "Eco, Balanced, Streaming, Gaming et Max.", listOf("Choisissez un profil sur le tableau. Il fixe les limites CPU par groupe, la fréquence GPU et le ventilateur par défaut.", "Page 2 → Profils ouvre l'éditeur : planification, ventilateur, limites CPU, limite et verrou GPU, Turbo.", "Ventilateur par défaut : Eco éteint, Balanced et Streaming bas, Gaming haut, Max maximal. « Réinitialiser » les rétablit.", "Après un redémarrage, le dernier profil revient, avec le mode de ventilateur choisi manuellement.")),
            "it" to Entry("Profili prestazioni", "Eco, Balanced, Streaming, Gaming e Max.", listOf("Scegli un profilo nel pannello. Imposta i limiti CPU per cluster, la frequenza GPU e la ventola predefinita.", "Pagina 2 → Profili apre l'editor: pianificazione, ventola, limiti CPU, limite e blocco GPU, Turbo.", "Ventola predefinita: Eco spenta, Balanced e Streaming bassa, Gaming alta, Max massima. “Ripristina” torna a questi valori.", "Dopo il riavvio torna l'ultimo profilo, con la modalità ventola scelta a mano.")),
            "zh" to Entry("性能配置", "Eco、Balanced、Streaming、Gaming 和 Max。", listOf("在仪表盘选择配置。它会设置各 CPU 集群上限、GPU 频率和默认风扇模式。", "第 2 页 →“配置”打开编辑器：调度模式、风扇、CPU 集群上限、GPU 上限与锁定、Turbo。", "默认风扇：Eco 关闭，Balanced 和 Streaming 低速，Gaming 高速，Max 全速。“重置”恢复这些值。", "重启后会恢复上次的配置，以及你手动选择的风扇模式。"))
        )),
        Topic("turbo", "max", mapOf(
            "en" to Entry("Turbo boost", "Keeps CPU and GPU at the top of the profile's limits.", listOf("Turn it on per profile in the profile editor (block “TURBO”). It runs only while that profile is active.", "Uses the performance governor, keeps all cores awake, gives the app on screen fast cores and stops the GPU from napping between frames.", "It is not an overclock: clocks never exceed the hardware maximum. Expect steadier FPS rather than higher peaks.", "Safety: above 92 °C for 20 s Turbo backs off; it returns after 30 s below 80 °C. Original values are restored when it stops.", "Uses more power and heat — pair it with a High or Max fan.")),
            "ru" to Entry("Турбо-буст", "Держит CPU и GPU на верхней границе лимитов профиля.", listOf("Включается для каждого профиля в редакторе (блок «ТУРБО») и работает, только пока этот профиль выбран.", "Регулятор performance, все ядра активны, приложению на экране — быстрые ядра, GPU не засыпает между кадрами.", "Это не разгон: частоты не превышают заводской максимум. Ждать стоит ровного FPS, а не новых пиков.", "Защита: выше 92 °C в течение 20 с Турбо отключается и возвращается после 30 с ниже 80 °C. При выключении исходные значения восстанавливаются.", "Больше расход и нагрев — лучше вместе с вентилятором High или Max.")),
            "nl" to Entry("Turbo-boost", "Houdt CPU en GPU op de bovengrens van het profiel.", listOf("Per profiel aan te zetten in de profieleditor (blok “TURBO”). Werkt alleen zolang dat profiel actief is.", "Performance-governor, alle kernen wakker, snelle kernen voor de app op het scherm en een GPU die niet sluimert tussen frames.", "Geen overklokken: de klok blijft onder het hardwaremaximum. Verwacht stabielere FPS, geen hogere pieken.", "Veiligheid: boven 92 °C gedurende 20 s schakelt Turbo terug; na 30 s onder 80 °C weer aan. Bij stoppen worden de originele waarden hersteld.", "Meer verbruik en warmte — combineer met ventilator Hoog of Max.")),
            "es" to Entry("Turbo", "Mantiene CPU y GPU en el máximo del perfil.", listOf("Actívalo por perfil en el editor (bloque “TURBO”). Solo funciona mientras ese perfil está activo.", "Gobernador performance, todos los núcleos despiertos, núcleos rápidos para la app en pantalla y GPU sin reposo entre fotogramas.", "No es overclock: nunca supera la frecuencia máxima. Espera FPS más estables, no picos mayores.", "Seguridad: por encima de 92 °C durante 20 s se retira; vuelve tras 30 s por debajo de 80 °C. Al parar se restauran los valores originales.", "Más consumo y calor: úsalo con ventilador alto o máximo.")),
            "de" to Entry("Turbo-Boost", "Hält CPU und GPU an der Obergrenze des Profils.", listOf("Pro Profil im Profileditor (Block „TURBO“) einschalten. Läuft nur, solange dieses Profil aktiv ist.", "Performance-Governor, alle Kerne wach, schnelle Kerne für die App im Vordergrund, GPU ohne Pausen zwischen Frames.", "Kein Übertakten: der Takt bleibt unter dem Hardware-Maximum. Erwarte stabilere FPS statt höherer Spitzen.", "Sicherheit: über 92 °C für 20 s zieht sich Turbo zurück und kommt nach 30 s unter 80 °C wieder. Beim Beenden werden die Originalwerte wiederhergestellt.", "Mehr Verbrauch und Wärme — am besten mit Lüfter Hoch oder Max.")),
            "fr" to Entry("Turbo", "Maintient CPU et GPU au maximum du profil.", listOf("À activer par profil dans l'éditeur (bloc « TURBO »). Il ne fonctionne que tant que ce profil est actif.", "Gouverneur performance, tous les cœurs éveillés, cœurs rapides pour l'app à l'écran, GPU sans pause entre les images.", "Ce n'est pas de l'overclocking : la fréquence ne dépasse jamais le maximum. Attendez-vous à des FPS plus stables, pas plus élevés.", "Sécurité : au-dessus de 92 °C pendant 20 s, Turbo se retire ; il revient après 30 s sous 80 °C. Les valeurs d'origine sont restaurées à l'arrêt.", "Plus de consommation et de chaleur : associez-le à un ventilateur haut ou maximal.")),
            "it" to Entry("Turbo", "Mantiene CPU e GPU al massimo del profilo.", listOf("Si attiva per profilo nell'editor (blocco “TURBO”) e funziona solo con quel profilo attivo.", "Governor performance, tutti i core attivi, core veloci per l'app in primo piano, GPU senza pause tra i fotogrammi.", "Non è overclock: la frequenza non supera mai il massimo. Aspettati FPS più stabili, non picchi più alti.", "Sicurezza: sopra 92 °C per 20 s Turbo si ritira; torna dopo 30 s sotto 80 °C. Allo stop i valori originali vengono ripristinati.", "Più consumo e calore: usalo con ventola alta o massima.")),
            "zh" to Entry("Turbo 加速", "让 CPU 和 GPU 保持在配置上限。", listOf("在配置编辑器（“TURBO”区块）中为每个配置单独开启，只在该配置启用时生效。", "使用 performance 调速器，所有核心保持唤醒，前台应用优先使用大核，GPU 帧间不休眠。", "这不是超频：频率不会超过硬件上限。效果是 FPS 更稳定，而不是峰值更高。", "安全：高于 92 °C 持续 20 秒会自动退出，低于 80 °C 持续 30 秒后恢复。停止时会还原原始数值。", "功耗和发热更高——建议配合高速或全速风扇。"))
        )),
        Topic("fan", "fan", mapOf(
            "en" to Entry("Fan & overheat protection", "Fan modes, custom curve and a safety net when the fan is off.", listOf("Tap the fan card to choose Off, Low, High, Max or a custom curve. A profile sets the default; your manual choice wins until you pick another profile.", "Overheat protection (on by default) works only when the fan is off: above 70 °C for 1 min → low, above 82 °C for 1 min → 50 %, above 90 °C for 2 min → 100 %.", "It steps back one level after cooling for a minute (below 65 °C, 80 °C, 90 °C). Short spikes are ignored.", "The fan icon only spins while the fan really turns.")),
            "ru" to Entry("Вентилятор и защита от перегрева", "Режимы, своя кривая и страховка при выключенном вентиляторе.", listOf("Нажми карточку вентилятора: Выкл., Низкий, Высокий, Макс. или своя кривая. Профиль задаёт режим по умолчанию, ручной выбор действует до смены профиля.", "Защита от перегрева (включена по умолчанию) работает только при выключенном вентиляторе: выше 70 °C 1 мин — низкие обороты, выше 82 °C 1 мин — 50 %, выше 90 °C 2 мин — 100 %.", "Возврат на ступень ниже — после минуты остывания (ниже 65 °C, 80 °C, 90 °C). Короткие скачки игнорируются.", "Иконка вентилятора крутится, только когда он действительно вращается.")),
            "nl" to Entry("Ventilator en oververhittingsbeveiliging", "Modi, eigen curve en een vangnet als de ventilator uit staat.", listOf("Tik op de ventilatorkaart: Uit, Laag, Hoog, Max of eigen curve. Een profiel stelt de standaard in; je eigen keuze geldt tot je een ander profiel kiest.", "Beveiliging (standaard aan) werkt alleen met ventilator uit: boven 70 °C 1 min → laag, boven 82 °C 1 min → 50 %, boven 90 °C 2 min → 100 %.", "Na een minuut afkoelen gaat hij een stap terug (onder 65 °C, 80 °C, 90 °C). Korte pieken worden genegeerd.", "Het ventilatoricoon draait alleen als de ventilator echt draait.")),
            "es" to Entry("Ventilador y protección térmica", "Modos, curva propia y una red de seguridad con el ventilador apagado.", listOf("Toca la tarjeta del ventilador: apagado, bajo, alto, máximo o curva propia. El perfil fija el modo por defecto; tu elección manual manda hasta cambiar de perfil.", "La protección (activa por defecto) solo actúa con el ventilador apagado: más de 70 °C 1 min → bajo, más de 82 °C 1 min → 50 %, más de 90 °C 2 min → 100 %.", "Baja un nivel tras un minuto enfriando (por debajo de 65 °C, 80 °C, 90 °C). Ignora picos breves.", "El icono del ventilador solo gira cuando el ventilador gira de verdad.")),
            "de" to Entry("Lüfter und Überhitzungsschutz", "Modi, eigene Kurve und Schutz bei ausgeschaltetem Lüfter.", listOf("Tippe auf die Lüfterkarte: Aus, Niedrig, Hoch, Max oder eigene Kurve. Das Profil setzt den Standard; deine Wahl gilt bis zum nächsten Profilwechsel.", "Der Schutz (standardmäßig an) greift nur bei ausgeschaltetem Lüfter: über 70 °C 1 min → niedrig, über 82 °C 1 min → 50 %, über 90 °C 2 min → 100 %.", "Nach einer Minute Abkühlung geht es eine Stufe zurück (unter 65 °C, 80 °C, 90 °C). Kurze Spitzen werden ignoriert.", "Das Lüftersymbol dreht sich nur, wenn der Lüfter wirklich läuft.")),
            "fr" to Entry("Ventilateur et protection thermique", "Modes, courbe perso et filet de sécurité ventilateur éteint.", listOf("Touchez la carte ventilateur : éteint, bas, haut, max ou courbe perso. Le profil fixe le défaut ; votre choix manuel prime jusqu'au prochain profil.", "La protection (active par défaut) n'agit que ventilateur éteint : plus de 70 °C 1 min → bas, plus de 82 °C 1 min → 50 %, plus de 90 °C 2 min → 100 %.", "Elle redescend d'un cran après une minute de refroidissement (sous 65 °C, 80 °C, 90 °C). Les pics courts sont ignorés.", "L'icône du ventilateur ne tourne que si le ventilateur tourne vraiment.")),
            "it" to Entry("Ventola e protezione termica", "Modalità, curva personale e protezione a ventola spenta.", listOf("Tocca la scheda ventola: spenta, bassa, alta, max o curva personale. Il profilo imposta il default; la scelta manuale vale fino al cambio profilo.", "La protezione (attiva di default) agisce solo a ventola spenta: oltre 70 °C 1 min → bassa, oltre 82 °C 1 min → 50 %, oltre 90 °C 2 min → 100 %.", "Scende di un livello dopo un minuto di raffreddamento (sotto 65 °C, 80 °C, 90 °C). I picchi brevi sono ignorati.", "L'icona della ventola gira solo se la ventola gira davvero.")),
            "zh" to Entry("风扇与过热保护", "风扇模式、自定义曲线，以及风扇关闭时的安全保护。", listOf("点按风扇卡片：关闭、低速、高速、全速或自定义曲线。配置决定默认模式，手动选择在切换配置前一直有效。", "过热保护（默认开启）仅在风扇关闭时生效：高于 70 °C 持续 1 分钟 → 低速，高于 82 °C 持续 1 分钟 → 50%，高于 90 °C 持续 2 分钟 → 100%。", "降温一分钟后降一级（低于 65 °C、80 °C、90 °C）。短暂波动会被忽略。", "风扇图标只在风扇真正转动时旋转。"))
        )),
        Topic("games", "gaming", mapOf(
            "en" to Entry("Game profiles", "Your own settings for each favorite app — up to 20.", listOf("On the Favorites page hold an app → “Set up game profile”: fan, CPU and GPU limits, GPU lock, Turbo, button layout and vibration.", "“Set up equalizer” gives the game its own sound: Keep (your usual equalizer), Own settings, or Off.", "Starting the app from Favorites applies its profile. When the game closes, PocketHub brings back your previous profile, controller settings and equalizer.", "Hold the tile → “Back to normal profile” to return at any time.")),
            "ru" to Entry("Профили игр", "Свои настройки для каждого приложения из избранного — до 20.", listOf("На странице избранного удерживай приложение → «Настроить профиль игры»: вентилятор, пределы CPU и GPU, фиксация GPU, Турбо, раскладка кнопок и вибрация.", "«Настроить эквалайзер» задаёт игре свой звук: «Не менять» (обычный эквалайзер), «Свой» или «Выключить».", "Запуск из избранного включает профиль игры. Когда игра закрывается, PocketHub возвращает прежний профиль, настройки контроллера и эквалайзер.", "Удерживай плитку → «Вернуть обычный профиль», чтобы вернуться в любой момент.")),
            "nl" to Entry("Gameprofielen", "Eigen instellingen per favoriete app — tot 20.", listOf("Houd op de favorietenpagina een app vast → “Gameprofiel instellen”: ventilator, CPU- en GPU-limieten, GPU-vergrendeling, Turbo, knopindeling en trilling.", "“Equalizer instellen” geeft de game eigen geluid: Behouden (je gewone equalizer), Eigen of Uit.", "Starten vanuit favorieten past het profiel toe. Na het sluiten zet PocketHub je vorige profiel, controller en equalizer terug.", "Houd de tegel vast → “Terug naar normaal profiel” om op elk moment terug te gaan.")),
            "es" to Entry("Perfiles de juego", "Ajustes propios para cada app favorita — hasta 20.", listOf("En favoritos mantén pulsada una app → “Configurar perfil de juego”: ventilador, límites de CPU y GPU, bloqueo de GPU, Turbo, distribución y vibración.", "“Ajustar ecualizador” da al juego su propio sonido: Mantener (tu ecualizador habitual), Propio o Apagado.", "Abrir la app desde favoritos aplica su perfil. Al cerrar el juego, PocketHub devuelve el perfil, el mando y el ecualizador anteriores.", "Mantén pulsada la ficha → “Volver al perfil normal” en cualquier momento.")),
            "de" to Entry("Spielprofile", "Eigene Einstellungen pro Favoriten-App — bis zu 20.", listOf("Auf der Favoritenseite eine App halten → „Spielprofil einrichten“: Lüfter, CPU- und GPU-Grenzen, GPU-Sperre, Turbo, Tastenlayout und Vibration.", "„Equalizer einrichten“ gibt dem Spiel eigenen Klang: Behalten (normaler Equalizer), Eigene Einstellungen oder Aus.", "Start aus den Favoriten wendet das Profil an. Nach dem Schließen stellt PocketHub Profil, Controller und Equalizer wieder her.", "Kachel halten → „Zurück zum normalen Profil“ jederzeit.")),
            "fr" to Entry("Profils de jeu", "Réglages propres à chaque app favorite — jusqu'à 20.", listOf("Dans les favoris, maintenez une app → « Configurer le profil de jeu » : ventilateur, limites CPU et GPU, verrou GPU, Turbo, disposition et vibration.", "« Régler l'égaliseur » donne au jeu son propre son : Conserver (égaliseur habituel), Personnalisé ou Désactivé.", "Lancer l'app depuis les favoris applique son profil. À la fermeture, PocketHub rétablit profil, manette et égaliseur précédents.", "Maintenez la vignette → « Revenir au profil normal » à tout moment.")),
            "it" to Entry("Profili di gioco", "Impostazioni proprie per ogni app preferita — fino a 20.", listOf("Nei preferiti tieni premuta un'app → “Configura profilo di gioco”: ventola, limiti CPU e GPU, blocco GPU, Turbo, layout tasti e vibrazione.", "“Imposta equalizzatore” dà al gioco il suo suono: Mantieni (equalizzatore abituale), Personale o Spento.", "Avviare l'app dai preferiti applica il profilo. Alla chiusura PocketHub ripristina profilo, controller ed equalizzatore precedenti.", "Tieni premuta la scheda → “Torna al profilo normale” in qualsiasi momento.")),
            "zh" to Entry("游戏配置", "为每个收藏应用单独设置 — 最多 20 个。", listOf("在收藏页长按应用 → “设置游戏配置”：风扇、CPU 与 GPU 限制、GPU 锁定、Turbo、按键布局和振动。", "“设置均衡器”为游戏单独设定声音：保持（常用均衡器）、自定义或关闭。", "从收藏启动应用会应用其配置。游戏关闭后，PocketHub 恢复之前的配置、手柄设置和均衡器。", "长按磁贴 → “恢复常规配置”可随时返回。"))
        )),
        Topic("tuning", "fps", mapOf(
            "en" to Entry("Game tuning: page & profiles", "Page 4: your own profiles for games — also for one game inside GameHub or an emulator.", listOf("The top block shows what runs on the top screen: the app, the game recognised inside it, its live FPS and the active profile. It refreshes every 3 seconds.", "Recognition: in GameHub / Winlator PocketHub reads the name of the running .exe (Wine helpers and launchers like Steam are skipped); in emulators it reads the ROM file the emulator keeps open (.nsp, .xci, .iso, .rvz…). Some emulators (e.g. RetroArch) load the ROM into memory and close the file — then bind the profile to the whole app or switch it by hand.", "Save profile: copies the settings of the active profile, asks for a name and opens the editor — CPU limit per cluster, GPU limit and lock, fan and Turbo. Built-in profiles (Eco … Max) are never changed.", "Binding (⋯ → Bind to): this game, the whole app, or no binding (manual only). A profile for one game wins over a profile for the whole app.", "On and off: tap a profile to switch it on. To go back to the system profile you used before, tap the active one (●) again, press “Back to system profile”, choose “Turn off” in its ⋯ menu, or pick Eco … Max on the dashboard.", "Automatic switching: every 5 seconds PocketHub checks the top screen. When a game with a bound profile runs, its profile switches on; about 10 seconds after the game closes, the previous system profile returns. If you switch the profile off while the game runs, it stays off until the game is closed. A Favorites game profile for the whole app is kept unless your profile is for one game inside it.", "⋯ menu: switch on / off, frequencies, fan & Turbo, auto-tune again, mode (fixed or adaptive with a frame rate), rename, binding, automatic switching on / off, delete.", "The ⋯ menu also has “Heat / noise limit”: set Quiet, a temperature target or FPS only for any profile — also one you saved by hand. With a limit, fixed profiles get a heat guard too: over the limit the CPU / GPU go down, when cool they return to the profile's limits.", "During a game, the Quick profile switch window (from a remapped button) shows the built-in profiles, your profiles, the Quiet mode switch and an Auto-tune button.", "Home screens are never treated as games: the Android launcher, AYA Home, PocketHub Launcher and any other launcher are ignored by game detection and auto-switching.")),
            "ru" to Entry("Тюнинг игр: страница и профили", "Страница 4: свои профили для игр — в том числе для отдельной игры внутри GameHub или эмулятора.", listOf("Верхний блок показывает, что запущено на верхнем экране: приложение, распознанную внутри него игру, текущий FPS и активный профиль. Обновляется каждые 3 секунды.", "Распознавание: в GameHub / Winlator PocketHub берёт имя запущенного .exe (служебные программы Wine и лаунчеры вроде Steam пропускаются); в эмуляторах — файл ROM, который эмулятор держит открытым (.nsp, .xci, .iso, .rvz…). Некоторые эмуляторы (например, RetroArch) загружают ROM в память и закрывают файл — тогда привяжи профиль ко всему приложению или включай его вручную.", "«Сохранить профиль»: копирует настройки активного профиля, спрашивает название и открывает редактор — лимит CPU по кластерам, лимит и фиксация GPU, вентилятор и турбо. Встроенные профили (Эко … Максимум) не меняются.", "Привязка (⋯ → «Привязать к…»): к этой игре, ко всему приложению или без привязки (только вручную). Профиль для конкретной игры важнее профиля для всего приложения.", "Включение и выключение: нажми на профиль, чтобы включить его. Чтобы вернуть системный профиль, который был до него, нажми на активный (●) ещё раз, кнопку «Вернуть системный профиль», пункт «Выключить» в его меню ⋯ или выбери Эко … Максимум на главной панели.", "Автовключение: каждые 5 секунд PocketHub смотрит на верхний экран. Когда запущена игра с привязанным профилем, он включается; примерно через 10 секунд после закрытия игры возвращается прежний системный профиль. Если выключить профиль во время игры, он не включится снова, пока игра не будет закрыта. Профиль игры из «Избранного» для всего приложения сохраняется, если твой профиль не для отдельной игры внутри него.", "Меню ⋯: включить / выключить, частоты, вентилятор и турбо, подобрать заново, режим (фиксированный или адаптивный с нужным FPS), переименовать, привязка, автовключение, удалить.", "В меню ⋯ есть и «Предел тепла / шума»: задай «Тишину», целевую температуру или «Только FPS» для любого профиля — в том числе сохранённого вручную. С пределом фиксированные профили тоже получают защиту: выше предела CPU / GPU снижаются, когда чип остынет — возвращаются к частотам профиля.", "Во время игры окно «Быстрая смена профиля» (с переназначенной кнопки) показывает встроенные профили, твои профили, переключатель «Тихий режим» и кнопку автоподбора.", "Рабочие столы никогда не считаются игрой: лаунчер Android, AYA Home, PocketHub Launcher и любые другие лаунчеры автоопределение и автопереключение пропускают.")),
            "nl" to Entry("Game-afstemming: pagina en profielen", "Pagina 4: eigen profielen voor games — ook voor één game in GameHub of een emulator.", listOf("Het bovenste blok toont wat op het bovenste scherm draait: de app, de herkende game erin, de actuele FPS en het actieve profiel. Elke 3 seconden ververst.", "Herkenning: in GameHub / Winlator leest PocketHub de naam van de lopende .exe (Wine-hulpprogramma’s en launchers zoals Steam worden overgeslagen); in emulators het ROM-bestand dat open blijft (.nsp, .xci, .iso, .rvz…). Sommige emulators (zoals RetroArch) laden de ROM in het geheugen en sluiten het bestand — koppel het profiel dan aan de hele app of kies het handmatig.", "Profiel opslaan: kopieert de instellingen van het actieve profiel, vraagt een naam en opent de editor — CPU-limiet per cluster, GPU-limiet en vastzetten, ventilator en Turbo. Ingebouwde profielen (Eco … Max) veranderen nooit.", "Koppeling (⋯ → Koppelen aan): deze game, de hele app of niets (alleen handmatig). Een profiel voor één game gaat voor een profiel voor de hele app.", "Aan en uit: tik op een profiel om het aan te zetten. Terug naar het systeemprofiel van daarvoor: tik nogmaals op het actieve (●), druk op “Terug naar systeemprofiel”, kies “Uitzetten” in het ⋯-menu of kies Eco … Max op het dashboard.", "Automatisch wisselen: elke 5 seconden kijkt PocketHub naar het bovenste scherm. Draait een game met een gekoppeld profiel, dan gaat dat aan; ongeveer 10 seconden na het sluiten komt het vorige systeemprofiel terug. Zet je het profiel tijdens het spelen uit, dan blijft het uit tot de game gesloten is. Een favorieten-gameprofiel voor de hele app blijft, tenzij jouw profiel voor één game daarin is.", "⋯-menu: aan / uit, frequenties, ventilator en Turbo, opnieuw afstemmen, modus (vast of adaptief met een FPS), hernoemen, koppeling, automatisch wisselen, verwijderen.", "Het ⋯-menu heeft ook “Warmte- / geluidslimiet”: stel Stilte, een doeltemperatuur of Alleen FPS in voor elk profiel — ook een handmatig opgeslagen. Met een limiet krijgen vaste profielen ook een warmtebewaking: boven de limiet gaan CPU / GPU omlaag, afgekoeld terug naar de limieten van het profiel.", "Tijdens een game toont het venster Profiel snel wisselen (via een toegewezen knop) de ingebouwde profielen, je eigen profielen, de schakelaar Stille modus en een knop Auto-afstemmen.", "Startschermen tellen nooit als game: de Android-launcher, AYA Home, PocketHub Launcher en andere launchers worden door detectie en automatisch wisselen genegeerd.")),
            "es" to Entry("Ajuste de juegos: página y perfiles", "Página 4: perfiles propios para juegos, también para un juego dentro de GameHub o un emulador.", listOf("El bloque superior muestra lo que corre en la pantalla superior: la app, el juego reconocido dentro, sus FPS actuales y el perfil activo. Se actualiza cada 3 segundos.", "Reconocimiento: en GameHub / Winlator PocketHub lee el nombre del .exe en marcha (se omiten los auxiliares de Wine y lanzadores como Steam); en emuladores, el archivo ROM que el emulador mantiene abierto (.nsp, .xci, .iso, .rvz…). Algunos emuladores (p. ej. RetroArch) cargan la ROM en memoria y cierran el archivo: entonces vincula el perfil a toda la app o actívalo a mano.", "Guardar perfil: copia los ajustes del perfil activo, pide un nombre y abre el editor: límite de CPU por clúster, límite y bloqueo de GPU, ventilador y Turbo. Los perfiles integrados (Eco … Máx.) no cambian.", "Vínculo (⋯ → Vincular a): este juego, toda la app o nada (solo manual). Un perfil para un juego concreto gana a uno para toda la app.", "Activar y desactivar: toca un perfil para activarlo. Para volver al perfil del sistema anterior, toca otra vez el activo (●), pulsa «Volver al perfil del sistema», elige «Desactivar» en su menú ⋯ o elige Eco … Máx. en el panel.", "Cambio automático: cada 5 segundos PocketHub mira la pantalla superior. Si corre un juego con perfil vinculado, se activa; unos 10 segundos después de cerrarlo vuelve el perfil del sistema anterior. Si lo desactivas durante el juego, no vuelve hasta que el juego se cierre. Un perfil de juego de Favoritos para toda la app se mantiene salvo que tu perfil sea para un juego dentro de ella.", "Menú ⋯: activar / desactivar, frecuencias, ventilador y Turbo, reajustar, modo (fijo o adaptativo con unos FPS), renombrar, vínculo, cambio automático, eliminar.", "El menú ⋯ también tiene «Límite de calor / ruido»: pon Silencio, una temperatura objetivo o Solo FPS en cualquier perfil, también uno guardado a mano. Con límite, los perfiles fijos también tienen protección térmica: por encima bajan CPU / GPU y al enfriarse vuelven a los límites del perfil.", "Durante el juego, la ventana Cambio rápido de perfil (desde un botón reasignado) muestra los perfiles integrados, los tuyos, el interruptor Modo silencioso y un botón de Autoajuste.", "Las pantallas de inicio nunca cuentan como juego: el launcher de Android, AYA Home, PocketHub Launcher y cualquier otro launcher se ignoran en la detección y el cambio automático.")),
            "de" to Entry("Spiel-Tuning: Seite und Profile", "Seite 4: eigene Profile für Spiele — auch für ein Spiel in GameHub oder einem Emulator.", listOf("Der obere Block zeigt, was oben läuft: die App, das darin erkannte Spiel, die aktuellen FPS und das aktive Profil. Aktualisierung alle 3 Sekunden.", "Erkennung: In GameHub / Winlator liest PocketHub den Namen der laufenden .exe (Wine-Hilfsprogramme und Launcher wie Steam werden übersprungen); in Emulatoren die ROM-Datei, die geöffnet bleibt (.nsp, .xci, .iso, .rvz…). Manche Emulatoren (z. B. RetroArch) laden die ROM in den Speicher und schließen die Datei — dann das Profil an die ganze App binden oder manuell wählen.", "Profil speichern: übernimmt die Einstellungen des aktiven Profils, fragt nach einem Namen und öffnet den Editor — CPU-Grenze pro Cluster, GPU-Grenze und -Sperre, Lüfter und Turbo. Eingebaute Profile (Eco … Max) bleiben unverändert.", "Bindung (⋯ → Binden an): dieses Spiel, die ganze App oder nichts (nur manuell). Ein Profil für ein einzelnes Spiel geht vor einem Profil für die ganze App.", "Ein und aus: Profil antippen schaltet es ein. Zurück zum vorherigen Systemprofil: das aktive (●) erneut antippen, „Zurück zum Systemprofil“ drücken, „Ausschalten“ im ⋯-Menü wählen oder Eco … Max im Dashboard wählen.", "Automatischer Wechsel: Alle 5 Sekunden prüft PocketHub den oberen Bildschirm. Läuft ein Spiel mit gebundenem Profil, wird es aktiv; etwa 10 Sekunden nach dem Beenden kehrt das vorherige Systemprofil zurück. Schaltest du das Profil im Spiel aus, bleibt es aus, bis das Spiel beendet ist. Ein Favoriten-Spielprofil für die ganze App bleibt, außer dein Profil gilt für ein Spiel darin.", "⋯-Menü: ein / aus, Frequenzen, Lüfter und Turbo, neu abstimmen, Modus (fest oder adaptiv mit FPS-Ziel), umbenennen, Bindung, automatischer Wechsel, löschen.", "Das ⋯-Menü hat auch „Wärme- / Geräuschgrenze“: Ruhe, ein Temperaturziel oder Nur FPS für jedes Profil festlegen — auch für ein manuell gespeichertes. Mit Grenze erhalten feste Profile einen Wärmeschutz: darüber sinken CPU / GPU, abgekühlt kehren sie zu den Profilgrenzen zurück.", "Im Spiel zeigt das Fenster Schneller Profilwechsel (über eine belegte Taste) die eingebauten Profile, deine Profile, den Schalter Leiser Modus und eine Auto-Tuning-Taste.", "Startbildschirme gelten nie als Spiel: Android-Launcher, AYA Home, PocketHub Launcher und andere Launcher werden von Erkennung und automatischem Wechsel ignoriert.")),
            "fr" to Entry("Réglage des jeux : page et profils", "Page 4 : vos profils pour les jeux — aussi pour un jeu dans GameHub ou un émulateur.", listOf("Le bloc du haut montre ce qui tourne sur l’écran du haut : l’app, le jeu reconnu dedans, ses FPS actuels et le profil actif. Actualisé toutes les 3 secondes.", "Reconnaissance : dans GameHub / Winlator, PocketHub lit le nom du .exe lancé (les utilitaires Wine et les lanceurs comme Steam sont ignorés) ; dans les émulateurs, le fichier ROM gardé ouvert (.nsp, .xci, .iso, .rvz…). Certains émulateurs (ex. RetroArch) chargent la ROM en mémoire et ferment le fichier — liez alors le profil à toute l’app ou activez-le à la main.", "Enregistrer un profil : copie les réglages du profil actif, demande un nom et ouvre l’éditeur — limite CPU par cluster, limite et verrouillage GPU, ventilateur et Turbo. Les profils intégrés (Éco … Max) ne changent jamais.", "Liaison (⋯ → Lier à) : ce jeu, toute l’app ou rien (manuel). Un profil pour un jeu précis l’emporte sur un profil pour toute l’app.", "Activer et désactiver : touchez un profil pour l’activer. Pour revenir au profil système d’avant, touchez à nouveau l’actif (●), appuyez sur « Retour au profil système », choisissez « Désactiver » dans son menu ⋯ ou choisissez Éco … Max sur le tableau.", "Changement automatique : toutes les 5 secondes, PocketHub regarde l’écran du haut. Si un jeu avec un profil lié tourne, ce profil s’active ; environ 10 secondes après sa fermeture, le profil système précédent revient. Si vous le désactivez en jeu, il reste désactivé jusqu’à la fermeture du jeu. Un profil de jeu des favoris pour toute l’app est conservé sauf si votre profil vise un jeu dedans.", "Menu ⋯ : activer / désactiver, fréquences, ventilateur et Turbo, nouveau réglage, mode (fixe ou adaptatif avec des FPS), renommer, liaison, changement automatique, supprimer.", "Le menu ⋯ propose aussi « Limite de chaleur / bruit » : Silence, une température cible ou FPS seulement pour n’importe quel profil, même enregistré à la main. Avec une limite, les profils fixes ont aussi une garde thermique : au-dessus, CPU / GPU baissent ; refroidis, ils reviennent aux limites du profil.", "En jeu, la fenêtre Changement rapide de profil (via un bouton réaffecté) affiche les profils intégrés, vos profils, l’interrupteur Mode silencieux et un bouton d’auto-réglage.", "Les écrans d'accueil ne comptent jamais comme jeu : le lanceur Android, AYA Home, PocketHub Launcher et tout autre lanceur sont ignorés par la détection et le changement automatique.")),
            "it" to Entry("Ottimizzazione giochi: pagina e profili", "Pagina 4: profili propri per i giochi — anche per un gioco dentro GameHub o un emulatore.", listOf("Il blocco in alto mostra cosa gira sullo schermo superiore: l’app, il gioco riconosciuto al suo interno, gli FPS attuali e il profilo attivo. Si aggiorna ogni 3 secondi.", "Riconoscimento: in GameHub / Winlator PocketHub legge il nome dell’.exe in esecuzione (gli strumenti di Wine e i launcher come Steam vengono saltati); negli emulatori il file ROM tenuto aperto (.nsp, .xci, .iso, .rvz…). Alcuni emulatori (es. RetroArch) caricano la ROM in memoria e chiudono il file: allora collega il profilo a tutta l’app o attivalo a mano.", "Salva profilo: copia le impostazioni del profilo attivo, chiede un nome e apre l’editor — limite CPU per cluster, limite e blocco GPU, ventola e Turbo. I profili integrati (Eco … Max) non cambiano mai.", "Collegamento (⋯ → Collega a): questo gioco, tutta l’app o niente (solo manuale). Un profilo per un singolo gioco vince su uno per tutta l’app.", "Attivare e disattivare: tocca un profilo per attivarlo. Per tornare al profilo di sistema di prima, tocca di nuovo quello attivo (●), premi «Torna al profilo di sistema», scegli «Disattiva» nel menu ⋯ o scegli Eco … Max nel pannello.", "Cambio automatico: ogni 5 secondi PocketHub controlla lo schermo superiore. Se gira un gioco con un profilo collegato, questo si attiva; circa 10 secondi dopo la chiusura torna il profilo di sistema precedente. Se lo disattivi durante il gioco, resta spento finché il gioco non viene chiuso. Un profilo di gioco dei Preferiti per tutta l’app resta, a meno che il tuo profilo sia per un gioco al suo interno.", "Menu ⋯: attiva / disattiva, frequenze, ventola e Turbo, nuovo auto-tuning, modalità (fissa o adattiva con FPS), rinomina, collegamento, cambio automatico, elimina.", "Il menu ⋯ ha anche «Limite di calore / rumore»: imposta Silenzio, una temperatura obiettivo o Solo FPS per qualsiasi profilo, anche salvato a mano. Con un limite anche i profili fissi hanno una protezione termica: oltre il limite CPU / GPU scendono, raffreddati tornano ai limiti del profilo.", "In gioco, la finestra Cambio rapido profilo (da un pulsante rimappato) mostra i profili integrati, i tuoi profili, l’interruttore Modalità silenziosa e un pulsante di auto-tuning.", "Le schermate home non contano mai come gioco: il launcher Android, AYA Home, PocketHub Launcher e ogni altro launcher sono ignorati da rilevamento e cambio automatico.")),
            "zh" to Entry("游戏调校：页面与配置", "第 4 页：为游戏建立自己的配置——也可针对 GameHub 或模拟器中的单个游戏。", listOf("顶部区域显示上屏正在运行的内容：应用、在其中识别到的游戏、实时 FPS 和当前配置，每 3 秒刷新一次。", "识别方式：在 GameHub / Winlator 中读取正在运行的 .exe 名称（会跳过 Wine 辅助程序和 Steam 等启动器）；在模拟器中读取其保持打开的 ROM 文件（.nsp、.xci、.iso、.rvz…）。部分模拟器（如 RetroArch）会把 ROM 读入内存后关闭文件——此时请把配置绑定到整个应用或手动切换。", "保存配置：复制当前配置的设置，输入名称后打开编辑器——各 CPU 簇上限、GPU 上限与锁定、风扇和 Turbo。内置配置（节能…极致）不会被修改。", "绑定（⋯ → 绑定到）：该游戏、整个应用或不绑定（仅手动）。针对单个游戏的配置优先于整个应用的配置。", "开启与关闭：点击配置即可开启。要回到之前的系统配置，可再次点击当前配置（●）、点击“返回系统配置”、在 ⋯ 菜单中选“关闭”，或在仪表盘选择节能…极致。", "自动切换：PocketHub 每 5 秒检查上屏。运行绑定了配置的游戏时自动开启该配置；游戏关闭约 10 秒后恢复之前的系统配置。如果在游戏中关闭了配置，在游戏关闭前不会再次开启。收藏中针对整个应用的游戏配置会保留，除非你的配置针对其中的单个游戏。", "⋯ 菜单：开启 / 关闭、频率、风扇和 Turbo、重新调频、模式（固定或指定 FPS 的自适应）、重命名、绑定、自动切换、删除。", "⋯ 菜单中还有“温度 / 噪音上限”：可为任何配置（包括手动保存的）设置安静、目标温度或仅 FPS。设置上限后，固定配置也会有温度守护：超过上限时降低 CPU / GPU，冷却后恢复到配置的上限。", "游戏中，“快速切换配置”窗口（通过映射按键打开）显示内置配置、你的配置、安静模式开关和自动调频按钮。", "桌面启动器永远不会被视为游戏：Android 启动器、AYA Home、PocketHub Launcher 以及其他启动器都会被游戏识别和自动切换忽略。"))
        )),
        Topic("autotune", "max", mapOf(
            "en" to Entry("How auto-tune works", "Finds the lowest CPU / GPU limits that keep a game's frame rate — at the fan noise you choose.", listOf("Why: every frequency step comes with its own voltage, set by the chip's firmware. A lower ceiling keeps the chip on lower steps: less heat, a quieter fan, longer battery. Many games do not need the chip at full speed. (True undervolting is not possible on this chip — the firmware owns the voltages.)", "Before you start: be in gameplay, in a typical or heavy scene — not a menu, pause or loading screen — and keep playing normally. Choose the frame rate to keep (Auto, or 20–165 on the slider), the allowed drop for games without a frame cap (3, 5 or 10 %), and what to keep besides FPS: Quiet, Temperature or FPS only. It takes about 2–3 minutes, 2–4 more with a heat check (up to 6 with the body sensor).", "Step 1 — reference: everything at full speed, 3 s warm-up, 8 s of measuring. If the frame rate sits on 30, 60, 90… it is a frame cap and that number is the target; otherwise the target is the measured rate minus the allowed drop.", "Step 2 — search: GPU, prime core, big cores and little cores, one after another. Each is found by halving the range (binary search); every try waits 1.5 s and measures 5 s. A try passes when the average holds the target with no big dips. The lowest passing step plus one step of headroom is kept.", "Step 3 — check: all limits together for 8 s; if the game falls short, every part goes up one step.", "Step 4 — heat (Quiet or Temperature): PocketHub keeps the found limits and watches the chosen sensor for up to 4 minutes (6 for the slow body sensor). While the temperature heads past the limit, GPU and big cores go down a step in turn; it ends once it has stayed steady below the limit for a while. If that costs frame rate you choose: keep it quiet / cool with fewer FPS, or keep the FPS with a louder fan / warmer chip.", "Why one choice: frame rate, fan noise and temperature are tied — the chip's power is the heat and the fan takes it away — so only two of the three can be chosen and the third follows. Quiet: the fan stays at Silent, Quiet or Balanced and PocketHub keeps that level's safe temperature (66 / 78 / 86 °C). Temperature: you set a target (65–85 °C) on the hottest zone, the GPU (most games), the CPU (Switch / PS2 emulators) or, if the device has one, the body sensor (38–45 °C, what your hands feel); the fan may work as hard as it needs. FPS only: strongest fan, temperature within overheat protection.", "Result: before → after for each part, a name, automatic switching for the recognised game and the adaptive option; Save & apply or Discard. Stop, a menu or pause (no frames), another app on top or closing the window all put your previous profile back.", "Adaptive mode: starts from the saved limits and checks every 2 s. Below the target → GPU and big cores up a step (not within 3 °C of the noise limit); target held for 10 s → one step down, GPU and CPU in turn, never below about 15 % GPU / 25 % CPU; over the noise limit → down whatever the frame rate. Menus and pauses leave the limits alone. Its status shows on the tuning page.", "Quiet mode: every profile runs one noise level lower, and PocketHub lowers CPU / GPU while the chip is over that level's limit, then goes back up to the profile's limits when it cools. Overheat protection still works on top of everything.", "Tips: tune in a heavy scene; keep two profiles for one game (e.g. “quiet” and “cooling”) and switch them in the quick window; tune again after a game update or a change of emulator settings.")),
            "ru" to Entry("Как работает автоподбор", "Находит самые низкие частоты CPU / GPU, при которых игра держит FPS, — при выбранном шуме вентилятора.", listOf("Зачем: каждой ступени частоты соответствует своё напряжение, его задаёт прошивка чипа. Более низкий потолок держит чип на нижних ступенях: меньше нагрев, тише вентилятор, дольше батарея. Многим играм не нужен чип на максимуме. (Настоящий андервольтинг на этом чипе невозможен — напряжениями управляет прошивка.)", "Перед запуском: будь в самом геймплее, в типичной или тяжёлой сцене — не в меню, не на паузе и не на загрузке — и играй как обычно. Выбери FPS, который нужно держать («Авто» или 20–165 ползунком), допустимое падение для игр без ограничения кадров (3, 5 или 10 %) и что держать кроме FPS: «Тишину», «Температуру» или «Только FPS». Занимает около 2–3 минут, с проверкой нагрева — на 2–4 минуты дольше (с датчиком корпуса — до 6).", "Шаг 1 — эталон: всё на полной скорости, 3 с прогрева, 8 с замера. Если FPS стоит ровно на 30, 60, 90… — это ограничение кадров, и цель — это число; иначе цель — замеренный FPS минус допустимое падение.", "Шаг 2 — поиск: GPU, главное ядро, большие ядра и малые ядра по очереди. Каждый узел ищется делением диапазона пополам (двоичный поиск); каждая проба — 1,5 с ожидания и 5 с замера. Проба пройдена, если средний FPS держит цель без больших провалов. Оставляется самая низкая пройденная ступень плюс одна ступень запаса.", "Шаг 3 — проверка: все частоты вместе 8 секунд; если игра не дотягивает, каждый узел поднимается на ступень.", "Шаг 4 — нагрев («Тишина» или «Температура»): PocketHub держит найденные частоты и до 4 минут (для медленного датчика корпуса — до 6) следит за выбранным датчиком. Пока температура идёт выше предела, по очереди снижаются GPU и большие ядра; проверка заканчивается, когда температура какое-то время стабильно ниже предела. Если это стоит кадров, ты выбираешь: тихо / прохладно с меньшим FPS или полный FPS с более громким вентилятором / более горячим чипом.", "Почему один выбор: FPS, шум вентилятора и температура связаны — мощность чипа и есть нагрев, а вентилятор его отводит, — поэтому задать можно только две величины из трёх, третья получится сама. «Тишина»: вентилятор остаётся на уровне Бесшумно, Тихо или Баланс, а PocketHub держит безопасную температуру этого уровня (66 / 78 / 86 °C). «Температура»: ты задаёшь цель (65–85 °C) по самой горячей зоне, по GPU (большинство игр), по CPU (эмуляторы Switch / PS2) или, если он есть в аппарате, по датчику корпуса (38–45 °C — то, что чувствуют руки); вентилятор работает, сколько нужно. «Только FPS»: самый сильный обдув, температура — в рамках защиты от перегрева.", "Результат: было → стало по каждому узлу, название, автовключение для распознанной игры и адаптивный режим; «Сохранить и включить» или «Не сохранять». «Стоп», меню или пауза (нет кадров), другое приложение наверху или закрытие окна — во всех случаях возвращается прежний профиль.", "Адаптивный режим: стартует с сохранённых частот и проверяет каждые 2 секунды. Ниже цели — GPU и большие ядра на ступень выше (но не ближе 3 °C к пределу шума); цель держится 10 секунд — на ступень ниже, по очереди GPU и CPU, но не ниже примерно 15 % GPU / 25 % CPU; выше предела шума — вниз при любом FPS. В меню и на паузе частоты не трогаются. Состояние видно на странице тюнинга.", "«Тихий режим»: любой профиль работает на уровень шума тише, а PocketHub снижает CPU / GPU, пока чип горячее предела этого уровня, и возвращает частоты профиля, когда он остынет. Защита от перегрева работает поверх всего.", "Советы: подбирай в тяжёлой сцене; держи два профиля для одной игры (например, «тихо» и «охлаждение») и переключай их в быстром окне; подбирай заново после обновления игры или смены настроек эмулятора.")),
            "nl" to Entry("Zo werkt auto-afstemmen", "Zoekt de laagste CPU- / GPU-limieten die de FPS van een game behouden — bij het gekozen ventilatorgeluid.", listOf("Waarom: elke frequentiestap heeft een eigen spanning, die de firmware van de chip bepaalt. Een lager plafond houdt de chip op lagere stappen: minder warmte, een stillere ventilator, langere accuduur. Veel games hebben de chip niet op vol nodig. (Echt undervolten kan op deze chip niet — de firmware beheert de spanningen.)", "Vooraf: zit in het spel zelf, in een gewone of zware scène — geen menu, pauze of laadscherm — en speel gewoon door. Kies de vast te houden FPS (Auto, of 20–165 met de schuif), de toegestane daling voor games zonder FPS-limiet (3, 5 of 10 %) en wat je naast FPS wilt behouden: Stilte, Temperatuur of Alleen FPS. Duurt ongeveer 2–3 minuten, met warmtetest 2–4 langer (met de behuizingssensor tot 6).", "Stap 1 — referentie: alles op volle snelheid, 3 s opwarmen, 8 s meten. Staat de FPS precies op 30, 60, 90…, dan is dat een limiet en het doel; anders is het doel de gemeten FPS min de toegestane daling.", "Stap 2 — zoeken: GPU, prime-kern, grote kernen en kleine kernen na elkaar. Elk wordt gevonden door het bereik te halveren (binair zoeken); elke poging wacht 1,5 s en meet 5 s. Een poging slaagt als het gemiddelde het doel haalt zonder grote dips. De laagste geslaagde stap plus één stap marge blijft.", "Stap 3 — controle: alle limieten samen 8 s; haalt de game het niet, dan gaat elk onderdeel een stap omhoog.", "Stap 4 — warmte (Stilte of Temperatuur): PocketHub houdt de gevonden limieten en volgt de gekozen sensor tot 4 minuten (6 voor de trage behuizingssensor). Zolang de temperatuur richting de limiet gaat, zakken GPU en grote kernen om de beurt een stap; klaar als ze een tijd stabiel onder de limiet blijft. Kost dat FPS, dan kies je: stil / koel met minder FPS, of de FPS houden met een luidere ventilator / warmere chip.", "Waarom één keuze: FPS, ventilatorgeluid en temperatuur hangen samen — het vermogen van de chip is de warmte en de ventilator voert die af — dus je kiest er twee van de drie en de derde volgt. Stilte: de ventilator blijft op Stil, Rustig of Gebalanceerd en PocketHub houdt de veilige temperatuur van die stand (66 / 78 / 86 °C). Temperatuur: je kiest een doel (65–85 °C) op de heetste zone, de GPU (meeste games), de CPU (Switch- / PS2-emulators) of, als het apparaat er een heeft, de behuizingssensor (38–45 °C, wat je handen voelen); de ventilator werkt zo hard als nodig. Alleen FPS: sterkste koeling, temperatuur binnen de oververhittingsbeveiliging.", "Resultaat: voor → na per onderdeel, een naam, automatisch wisselen voor de herkende game en de adaptieve optie; Opslaan en toepassen of Weggooien. Stoppen, een menu of pauze (geen beelden), een andere app bovenaan of het venster sluiten zetten je vorige profiel terug.", "Adaptieve modus: begint bij de opgeslagen limieten en kijkt elke 2 s. Onder het doel → GPU en grote kernen een stap omhoog (niet binnen 3 °C van de geluidslimiet); doel 10 s gehaald → een stap omlaag, GPU en CPU om de beurt, nooit onder ongeveer 15 % GPU / 25 % CPU; boven de geluidslimiet → omlaag ongeacht de FPS. Menu’s en pauzes laten de limieten met rust. De status staat op de afstemmingspagina.", "Stille modus: elk profiel draait een geluidsniveau lager, en PocketHub verlaagt CPU / GPU zolang de chip boven de limiet van dat niveau zit, en gaat terug naar de limieten van het profiel als hij afkoelt. De oververhittingsbeveiliging werkt altijd daarbovenop.", "Tips: stem af in een zware scène; houd twee profielen voor één game (bijv. “stil” en “koeling”) en wissel ze in het snelle venster; stem opnieuw af na een game-update of andere emulatorinstellingen.")),
            "es" to Entry("Cómo funciona el autoajuste", "Busca los límites de CPU / GPU más bajos que mantienen los FPS de un juego, con el ruido de ventilador que elijas.", listOf("Por qué: cada escalón de frecuencia tiene su voltaje, que fija el firmware del chip. Un techo más bajo mantiene el chip en escalones bajos: menos calor, ventilador más silencioso, más batería. Muchos juegos no necesitan el chip a tope. (El undervolting real no es posible en este chip: el firmware controla los voltajes.)", "Antes de empezar: estate en plena partida, en una escena típica o exigente — no en un menú, pausa o carga — y sigue jugando. Elige los FPS a mantener (Auto, o 20–165 con el control), la caída permitida para juegos sin límite (3, 5 o 10 %) y qué mantener además de FPS: Silencio, Temperatura o Solo FPS. Tarda unos 2–3 minutos, 2–4 más con prueba de calor (hasta 6 con el sensor de carcasa).", "Paso 1 — referencia: todo a tope, 3 s de calentamiento y 8 s de medición. Si los FPS se quedan en 30, 60, 90… es un límite de FPS y ese número es el objetivo; si no, el objetivo es lo medido menos la caída permitida.", "Paso 2 — búsqueda: GPU, núcleo principal, núcleos grandes y pequeños, uno tras otro. Cada uno se busca partiendo el rango por la mitad (búsqueda binaria); cada prueba espera 1,5 s y mide 5 s. Pasa si la media mantiene el objetivo sin caídas grandes. Se queda el escalón más bajo que pasa más uno de margen.", "Paso 3 — comprobación: todos los límites juntos durante 8 s; si el juego no llega, cada parte sube un escalón.", "Paso 4 — calor (Silencio o Temperatura): PocketHub mantiene los límites hallados y vigila el sensor elegido hasta 4 minutos (6 con el lento sensor de carcasa). Mientras la temperatura se acerca al límite, bajan un escalón GPU y núcleos grandes por turnos; termina cuando se mantiene un rato estable bajo el límite. Si eso cuesta FPS, eliges: silencio / frescor con menos FPS, o los FPS con un ventilador más fuerte / chip más caliente.", "Por qué una sola elección: FPS, ruido del ventilador y temperatura están ligados — la potencia del chip es el calor y el ventilador lo saca —, así que solo se eligen dos de las tres y la tercera sale sola. Silencio: el ventilador se queda en Silencioso, Bajo o Equilibrado y PocketHub mantiene la temperatura segura de ese nivel (66 / 78 / 86 °C). Temperatura: eliges un objetivo (65–85 °C) en la zona más caliente, la GPU (la mayoría de juegos), la CPU (emuladores de Switch / PS2) o, si existe, el sensor de carcasa (38–45 °C, lo que notan tus manos); el ventilador trabaja lo necesario. Solo FPS: máxima refrigeración, temperatura dentro de la protección.", "Resultado: antes → después por parte, un nombre, cambio automático para el juego reconocido y la opción adaptativa; Guardar y aplicar o Descartar. Detener, un menú o pausa (sin fotogramas), otra app arriba o cerrar la ventana devuelven tu perfil anterior.", "Modo adaptativo: parte de los límites guardados y revisa cada 2 s. Por debajo del objetivo → GPU y núcleos grandes suben un escalón (no a menos de 3 °C del límite de ruido); objetivo mantenido 10 s → bajan un escalón, GPU y CPU por turnos, nunca por debajo de ~15 % GPU / 25 % CPU; por encima del límite de ruido → bajan pase lo que pase. Menús y pausas no tocan los límites. Su estado se ve en la página de ajuste.", "Modo silencioso: cualquier perfil va un nivel de ruido más bajo y PocketHub baja CPU / GPU mientras el chip supere el límite de ese nivel; al enfriarse vuelve a los límites del perfil. La protección contra sobrecalentamiento sigue actuando por encima.", "Consejos: ajusta en una escena exigente; ten dos perfiles para un juego (p. ej. «silencio» y «refrigeración») y cámbialos en la ventana rápida; reajusta tras una actualización del juego o un cambio de ajustes del emulador.")),
            "de" to Entry("So funktioniert Auto-Tuning", "Findet die niedrigsten CPU- / GPU-Grenzen, die die FPS eines Spiels halten — bei der gewählten Lüfterlautstärke.", listOf("Warum: Zu jeder Frequenzstufe gehört eine eigene Spannung, die die Chip-Firmware festlegt. Eine niedrigere Obergrenze hält den Chip auf unteren Stufen: weniger Wärme, leiserer Lüfter, längere Akkulaufzeit. Viele Spiele brauchen den Chip nicht auf voller Leistung. (Echtes Undervolting ist auf diesem Chip nicht möglich — die Firmware verwaltet die Spannungen.)", "Vorher: im eigentlichen Spiel sein, in einer typischen oder fordernden Szene — kein Menü, keine Pause, kein Ladebildschirm — und normal weiterspielen. FPS-Ziel wählen (Auto, oder 20–165 per Regler), erlaubten Abfall für Spiele ohne Begrenzung (3, 5 oder 10 %) und was neben FPS gehalten wird: Ruhe, Temperatur oder Nur FPS. Etwa 2–3 Minuten, mit Wärmetest 2–4 länger (mit dem Gehäusesensor bis zu 6).", "Schritt 1 — Referenz: alles auf voller Leistung, 3 s Aufwärmen, 8 s Messen. Liegen die FPS genau bei 30, 60, 90…, ist das eine Begrenzung und das Ziel; sonst ist das Ziel der Messwert minus dem erlaubten Abfall.", "Schritt 2 — Suche: GPU, Prime-Kern, große und kleine Kerne nacheinander. Jeder wird durch Halbieren des Bereichs gefunden (binäre Suche); jeder Versuch wartet 1,5 s und misst 5 s. Er besteht, wenn der Durchschnitt das Ziel ohne große Einbrüche hält. Die niedrigste bestandene Stufe plus eine Stufe Reserve bleibt.", "Schritt 3 — Prüfung: alle Grenzen zusammen 8 s; reicht es nicht, geht jeder Teil eine Stufe hoch.", "Schritt 4 — Wärme (Ruhe oder Temperatur): PocketHub behält die gefundenen Grenzen und beobachtet den gewählten Sensor bis zu 4 Minuten (6 beim trägen Gehäusesensor). Solange die Temperatur über die Grenze steuert, sinken GPU und große Kerne abwechselnd eine Stufe; Ende, wenn sie eine Weile stabil darunter bleibt. Kostet das FPS, wählst du: leise / kühl mit weniger FPS oder volle FPS mit lauterem Lüfter / wärmerem Chip.", "Warum nur eine Wahl: FPS, Lüftergeräusch und Temperatur hängen zusammen — die Leistung des Chips ist die Wärme, der Lüfter führt sie ab —, also lassen sich nur zwei von dreien wählen, die dritte ergibt sich. Ruhe: der Lüfter bleibt auf Lautlos, Leise oder Ausgewogen, PocketHub hält die sichere Temperatur dieser Stufe (66 / 78 / 86 °C). Temperatur: du wählst ein Ziel (65–85 °C) für die heißeste Zone, die GPU (meiste Spiele), die CPU (Switch- / PS2-Emulatoren) oder, falls vorhanden, den Gehäusesensor (38–45 °C, was die Hände spüren); der Lüfter arbeitet so stark wie nötig. Nur FPS: stärkste Maximal, Temperatur im Rahmen des Überhitzungsschutzes.", "Ergebnis: vorher → nachher je Teil, ein Name, automatischer Wechsel für das erkannte Spiel und die adaptive Option; Speichern und anwenden oder Verwerfen. Stopp, Menü oder Pause (keine Bilder), eine andere App oben oder das Schließen des Fensters stellen dein vorheriges Profil wieder her.", "Adaptiver Modus: startet bei den gespeicherten Grenzen und prüft alle 2 s. Unter dem Ziel → GPU und große Kerne eine Stufe hoch (nicht näher als 3 °C an der Geräuschgrenze); Ziel 10 s gehalten → eine Stufe runter, GPU und CPU abwechselnd, nie unter etwa 15 % GPU / 25 % CPU; über der Geräuschgrenze → runter, egal wie die FPS sind. Menüs und Pausen lassen die Grenzen unverändert. Der Status steht auf der Tuning-Seite.", "Leiser Modus: jedes Profil läuft eine Geräuschstufe leiser, und PocketHub senkt CPU / GPU, solange der Chip über der Grenze dieser Stufe liegt, und kehrt beim Abkühlen zu den Profilgrenzen zurück. Der Überhitzungsschutz wirkt immer zusätzlich.", "Tipps: in einer fordernden Szene abstimmen; zwei Profile pro Spiel halten (z. B. „leise“ und „Maximal“) und im Schnellfenster wechseln; nach einem Spiel-Update oder geänderten Emulator-Einstellungen neu abstimmen.")),
            "fr" to Entry("Fonctionnement de l’auto-réglage", "Trouve les limites CPU / GPU les plus basses qui gardent les FPS d’un jeu — au bruit de ventilateur choisi.", listOf("Pourquoi : chaque palier de fréquence a sa propre tension, fixée par le firmware de la puce. Un plafond plus bas garde la puce sur des paliers inférieurs : moins de chaleur, ventilateur plus discret, plus d’autonomie. Beaucoup de jeux n’ont pas besoin de la puce à fond. (Le vrai undervolting est impossible sur cette puce — le firmware gère les tensions.)", "Avant de commencer : soyez en pleine partie, dans une scène typique ou exigeante — pas un menu, une pause ou un chargement — et continuez à jouer. Choisissez les FPS à garder (Auto, ou 20–165 avec le curseur), la baisse permise pour les jeux sans limite (3, 5 ou 10 %) et ce qu’il faut garder en plus des FPS : Silence, Température ou FPS seulement. Environ 2–3 minutes, 2–4 de plus avec le test thermique (jusqu’à 6 avec le capteur de coque).", "Étape 1 — référence : tout à pleine vitesse, 3 s de chauffe, 8 s de mesure. Si les FPS restent pile sur 30, 60, 90…, c’est une limite et ce nombre est l’objectif ; sinon l’objectif est la valeur mesurée moins la baisse permise.", "Étape 2 — recherche : GPU, cœur principal, gros cœurs puis petits cœurs, l’un après l’autre. Chacun est trouvé en coupant la plage en deux (recherche binaire) ; chaque essai attend 1,5 s et mesure 5 s. Il réussit si la moyenne tient l’objectif sans grosses chutes. Le palier le plus bas réussi plus un palier de marge est gardé.", "Étape 3 — vérification : toutes les limites ensemble pendant 8 s ; si le jeu n’y arrive pas, chaque partie remonte d’un palier.", "Étape 4 — chaleur (Silence ou Température) : PocketHub garde les limites trouvées et surveille le capteur choisi jusqu’à 4 minutes (6 pour le lent capteur de coque). Tant que la température se dirige au-delà de la limite, GPU et gros cœurs baissent d’un palier à tour de rôle ; fin quand elle reste un moment stable en dessous. Si cela coûte des FPS, vous choisissez : silence / fraîcheur avec moins de FPS, ou les FPS avec un ventilateur plus bruyant / une puce plus chaude.", "Pourquoi un seul choix : FPS, bruit du ventilateur et température sont liés — la puissance de la puce est la chaleur et le ventilateur l’évacue —, on n’en choisit donc que deux sur trois, la troisième suit. Silence : le ventilateur reste en Silencieux, Calme ou Équilibré et PocketHub tient la température sûre de ce niveau (66 / 78 / 86 °C). Température : vous fixez un objectif (65–85 °C) sur la zone la plus chaude, le GPU (la plupart des jeux), le CPU (émulateurs Switch / PS2) ou, s’il existe, le capteur de coque (38–45 °C, ce que sentent vos mains) ; le ventilateur travaille autant que nécessaire. FPS seulement : refroidissement maximal, température dans les limites de la protection.", "Résultat : avant → après pour chaque partie, un nom, le changement automatique pour le jeu reconnu et l’option adaptative ; Enregistrer et appliquer ou Abandonner. Arrêter, un menu ou une pause (pas d’images), une autre app en haut ou la fermeture de la fenêtre remettent votre profil précédent.", "Mode adaptatif : part des limites enregistrées et vérifie toutes les 2 s. Sous l’objectif → GPU et gros cœurs montent d’un palier (pas à moins de 3 °C de la limite de bruit) ; objectif tenu 10 s → descente d’un palier, GPU et CPU à tour de rôle, jamais sous environ 15 % GPU / 25 % CPU ; au-dessus de la limite de bruit → descente quels que soient les FPS. Menus et pauses ne touchent pas aux limites. Son état s’affiche sur la page de réglage.", "Mode silencieux : chaque profil tourne un niveau de bruit plus bas, et PocketHub baisse CPU / GPU tant que la puce dépasse la limite de ce niveau, puis revient aux limites du profil quand elle refroidit. La protection contre la surchauffe agit toujours en plus.", "Conseils : réglez dans une scène exigeante ; gardez deux profils par jeu (ex. « silence » et « refroidissement ») et changez-les dans la fenêtre rapide ; refaites le réglage après une mise à jour du jeu ou un changement de réglages de l’émulateur.")),
            "it" to Entry("Come funziona l’auto-tuning", "Trova i limiti CPU / GPU più bassi che mantengono gli FPS di un gioco — con il rumore della ventola scelto.", listOf("Perché: ogni gradino di frequenza ha la sua tensione, decisa dal firmware del chip. Un tetto più basso tiene il chip sui gradini inferiori: meno calore, ventola più silenziosa, più batteria. Molti giochi non hanno bisogno del chip al massimo. (Il vero undervolting non è possibile su questo chip: le tensioni le gestisce il firmware.)", "Prima di iniziare: sii in pieno gioco, in una scena tipica o pesante — non un menu, una pausa o un caricamento — e continua a giocare. Scegli gli FPS da mantenere (Auto, o 20–165 con il cursore), il calo consentito per giochi senza limite (3, 5 o 10 %) e cosa mantenere oltre agli FPS: Silenzio, Temperatura o Solo FPS. Circa 2–3 minuti, 2–4 in più con la prova termica (fino a 6 con il sensore della scocca).", "Passo 1 — riferimento: tutto alla massima velocità, 3 s di riscaldamento, 8 s di misura. Se gli FPS restano esattamente su 30, 60, 90… è un limite e quel numero è l’obiettivo; altrimenti l’obiettivo è il valore misurato meno il calo consentito.", "Passo 2 — ricerca: GPU, core principale, core grandi e core piccoli, uno dopo l’altro. Ognuno si trova dimezzando l’intervallo (ricerca binaria); ogni prova attende 1,5 s e misura 5 s. Passa se la media mantiene l’obiettivo senza grossi cali. Resta il gradino più basso superato più un gradino di margine.", "Passo 3 — verifica: tutti i limiti insieme per 8 s; se il gioco non ce la fa, ogni parte sale di un gradino.", "Passo 4 — calore (Silenzio o Temperatura): PocketHub mantiene i limiti trovati e osserva il sensore scelto fino a 4 minuti (6 per il lento sensore della scocca). Finché la temperatura punta oltre il limite, GPU e core grandi scendono di un gradino a turno; finisce quando resta per un po’ stabile sotto il limite. Se costa FPS, scegli: silenzio / fresco con meno FPS, o gli FPS con ventola più rumorosa / chip più caldo.", "Perché una sola scelta: FPS, rumore della ventola e temperatura sono legati — la potenza del chip è il calore e la ventola lo porta via —, quindi se ne scelgono solo due su tre e la terza segue. Silenzio: la ventola resta su Silenzioso, Basso o Bilanciato e PocketHub mantiene la temperatura sicura di quel livello (66 / 78 / 86 °C). Temperatura: scegli un obiettivo (65–85 °C) sulla zona più calda, la GPU (la maggior parte dei giochi), la CPU (emulatori Switch / PS2) o, se presente, il sensore della scocca (38–45 °C, ciò che sentono le mani); la ventola lavora quanto serve. Solo FPS: raffreddamento massimo, temperatura entro la protezione.", "Risultato: prima → dopo per ogni parte, un nome, il cambio automatico per il gioco riconosciuto e l’opzione adattiva; Salva e applica o Scarta. Stop, un menu o una pausa (nessun fotogramma), un’altra app in alto o la chiusura della finestra ripristinano il profilo precedente.", "Modalità adattiva: parte dai limiti salvati e controlla ogni 2 s. Sotto l’obiettivo → GPU e core grandi salgono di un gradino (non entro 3 °C dal limite di rumore); obiettivo mantenuto per 10 s → scendono di un gradino, GPU e CPU a turno, mai sotto circa 15 % GPU / 25 % CPU; oltre il limite di rumore → giù qualunque siano gli FPS. Menu e pause non toccano i limiti. Lo stato appare nella pagina di ottimizzazione.", "Modalità silenziosa: ogni profilo usa un livello di rumore più basso e PocketHub abbassa CPU / GPU finché il chip supera il limite di quel livello, poi torna ai limiti del profilo quando si raffredda. La protezione dal surriscaldamento agisce sempre in aggiunta.", "Consigli: fai il tuning in una scena pesante; tieni due profili per un gioco (es. «silenzio» e «raffreddamento») e cambiali nella finestra rapida; rifai il tuning dopo un aggiornamento del gioco o un cambio di impostazioni dell’emulatore.")),
            "zh" to Entry("自动调频的工作原理", "在你选择的风扇噪音下，找到能保持游戏 FPS 的最低 CPU / GPU 频率上限。", listOf("原理：每一级频率都对应由芯片固件设定的电压。降低频率上限能让芯片停留在较低档位：发热更少、风扇更安静、续航更长。很多游戏并不需要芯片满速运行。（这颗芯片无法真正降压——电压由固件控制。）", "开始之前：进入实际游戏，处于典型或较重的场景——不要在菜单、暂停或加载画面——并正常游玩。选择要保持的 FPS（自动、30、45、60、90）、无帧率上限游戏允许的下降（3、5 或 10 %），以及除 FPS 外要保持什么：安静、温度或仅 FPS。约需 2–3 分钟，加上温度检测再多 2–4 分钟（使用机身传感器最多 6 分钟）。", "第 1 步 — 基准：全部满速，预热 3 秒，测量 8 秒。如果 FPS 正好停在 30、60、90… 说明游戏有帧率上限，该数值即为目标；否则目标为测得的 FPS 减去允许的下降。", "第 2 步 — 搜索：依次调整 GPU、超大核、大核和小核。每项都用折半查找（二分搜索）确定；每次尝试等待 1.5 秒、测量 5 秒。平均 FPS 达到目标且没有明显掉帧即为通过。保留通过的最低档位，再加一级余量。", "第 3 步 — 检查：所有上限一起测试 8 秒；若达不到目标，每项再升高一级。", "第 4 步 — 温度（安静或温度目标）：PocketHub 保持找到的频率，最多观察所选传感器 4 分钟（反应较慢的机身传感器最多 6 分钟）。温度趋向超过上限时，轮流将 GPU 和大核降低一级；温度在上限以下稳定一段时间后结束。若因此损失 FPS，你可以选择：安静 / 低温但 FPS 较低，或保持 FPS 但风扇更响 / 芯片更热。", "为什么只能选一项：FPS、风扇噪音和温度相互关联——芯片功耗就是发热，风扇负责散热——因此三者只能指定两个，第三个随之确定。安静：风扇保持在静音、安静或均衡档，PocketHub 维持该档的安全温度（66 / 78 / 86 °C）。温度：你设定目标（65–85 °C），可选最热区域、GPU（大多数游戏）、CPU（Switch / PS2 模拟器），或设备具备时的机身传感器（38–45 °C，即手感温度）；风扇按需运转。仅 FPS：最强散热，温度在过热保护范围内。", "结果：显示每项调整前 → 后的频率、名称、针对识别到的游戏的自动切换以及自适应选项；可“保存并应用”或“放弃”。点击停止、进入菜单或暂停（没有画面）、上屏换成其他应用或关闭窗口，都会恢复你之前的配置。", "自适应模式：从保存的频率开始，每 2 秒检查一次。低于目标 → GPU 和大核升一级（距噪音温度上限 3 °C 以内时不升）；目标保持 10 秒 → 降一级，GPU 与 CPU 轮流，最低约为 GPU 15 % / CPU 25 %；超过噪音温度上限 → 无论 FPS 如何都降低。菜单和暂停时不改变频率。状态显示在调校页面上。", "安静模式：任何配置都降低一个噪音档位，芯片超过该档温度上限时 PocketHub 降低 CPU / GPU，冷却后再恢复到配置的上限。过热保护始终在此之上生效。", "建议：在较重的场景中调频；为同一游戏保留两个配置（例如“安静”和“最大”），在快速窗口中切换；游戏更新或模拟器设置变化后重新调频。"))
        )),
        Topic("favorites", "star", mapOf(
            "en" to Entry("Favorites", "Your apps on page 3, one tap away.", listOf("“+” adds an app from the installed list (with search).", "Tap an icon to open the app on the top screen.", "Hold an icon to open it on the bottom screen, move it left or right, set up a game profile or remove it.")),
            "ru" to Entry("Избранное", "Твои приложения на странице 3 — в одно касание.", listOf("«+» добавляет приложение из списка установленных (с поиском).", "Нажатие на иконку открывает приложение на верхнем экране.", "Удержание: открыть на нижнем экране, сдвинуть влево или вправо, настроить профиль игры или убрать из избранного.")),
            "nl" to Entry("Favorieten", "Je apps op pagina 3, met één tik.", listOf("“+” voegt een app toe uit de lijst met geïnstalleerde apps (met zoeken).", "Tik op een icoon om de app op het bovenste scherm te openen.", "Houd vast om op het onderste scherm te openen, te verplaatsen, een gameprofiel in te stellen of te verwijderen.")),
            "es" to Entry("Favoritos", "Tus apps en la página 3, a un toque.", listOf("“+” añade una app de la lista de instaladas (con búsqueda).", "Toca un icono para abrir la app en la pantalla superior.", "Mantén pulsado para abrirla abajo, moverla, configurar un perfil de juego o quitarla.")),
            "de" to Entry("Favoriten", "Deine Apps auf Seite 3, mit einem Tipp.", listOf("„+“ fügt eine installierte App hinzu (mit Suche).", "Tippe auf ein Symbol, um die App auf dem oberen Bildschirm zu öffnen.", "Halten: unten öffnen, verschieben, Spielprofil einrichten oder entfernen.")),
            "fr" to Entry("Favoris", "Vos apps en page 3, à portée d'un toucher.", listOf("« + » ajoute une app installée (avec recherche).", "Touchez une icône pour ouvrir l'app sur l'écran du haut.", "Maintenez pour l'ouvrir en bas, la déplacer, configurer un profil de jeu ou la retirer.")),
            "it" to Entry("Preferiti", "Le tue app a pagina 3, a portata di tocco.", listOf("“+” aggiunge un'app installata (con ricerca).", "Tocca un'icona per aprire l'app sullo schermo superiore.", "Tieni premuto per aprirla sotto, spostarla, configurare un profilo di gioco o rimuoverla.")),
            "zh" to Entry("收藏", "常用应用放在第 3 页，一点即开。", listOf("“+”可从已安装应用中添加（支持搜索）。", "点按图标在上屏打开应用。", "长按可在下屏打开、左右移动、设置游戏配置或移除。"))
        )),
        Topic("quick", "wifi", mapOf(
            "en" to Entry("Quick settings", "Page 4: switches for system functions.", listOf("Default tiles: Wi-Fi, Bluetooth and Auto-rotate. Tap to switch; active tiles light up.", "“+” adds Airplane mode, Location, Do not disturb, Battery saver, Dark theme and Force landscape.", "Force landscape locks the top screen horizontally, even for apps that want portrait.", "Hold a tile to open its system settings page, move it or remove it.")),
            "ru" to Entry("Быстрые настройки", "Страница 4: переключатели системных функций.", listOf("По умолчанию: Wi-Fi, Bluetooth и Автоповорот. Нажатие переключает, включённые плитки подсвечиваются.", "«+» добавляет режим полёта, местоположение, «Не беспокоить», энергосбережение, тёмную тему и «Альбомная всегда».", "«Альбомная всегда» фиксирует верхний экран горизонтально даже для приложений, которые просят портрет.", "Удержание плитки: открыть системные настройки, сдвинуть или убрать.")),
            "nl" to Entry("Snelle instellingen", "Pagina 4: schakelaars voor systeemfuncties.", listOf("Standaard: wifi, Bluetooth en automatisch draaien. Tik om te schakelen; actieve tegels lichten op.", "“+” voegt vliegtuigmodus, locatie, niet storen, batterijbesparing, donker thema en liggend forceren toe.", "Liggend forceren zet het bovenste scherm vast in liggende stand, ook voor apps die staand willen.", "Houd een tegel vast om de systeeminstelling te openen, te verplaatsen of te verwijderen.")),
            "es" to Entry("Ajustes rápidos", "Página 4: interruptores de funciones del sistema.", listOf("Por defecto: Wi-Fi, Bluetooth y giro automático. Toca para cambiar; los activos se iluminan.", "“+” añade modo avión, ubicación, no molestar, ahorro de batería, tema oscuro y forzar horizontal.", "Forzar horizontal fija la pantalla superior en horizontal, incluso para apps que piden vertical.", "Mantén un acceso para abrir sus ajustes, moverlo o quitarlo.")),
            "de" to Entry("Schnelleinstellungen", "Seite 4: Schalter für Systemfunktionen.", listOf("Standard: WLAN, Bluetooth und automatisches Drehen. Tippen schaltet um; aktive Kacheln leuchten.", "„+“ fügt Flugmodus, Standort, Nicht stören, Energiesparen, dunkles Design und Querformat erzwingen hinzu.", "Querformat erzwingen fixiert den oberen Bildschirm quer, auch für Apps, die Hochformat wollen.", "Kachel halten: Systemeinstellungen öffnen, verschieben oder entfernen.")),
            "fr" to Entry("Réglages rapides", "Page 4 : interrupteurs de fonctions système.", listOf("Par défaut : Wi-Fi, Bluetooth et rotation auto. Touchez pour basculer ; les tuiles actives s'allument.", "« + » ajoute mode avion, localisation, ne pas déranger, économiseur, thème sombre et paysage forcé.", "Paysage forcé bloque l'écran du haut à l'horizontale, même pour les apps en portrait.", "Maintenez une tuile pour ouvrir ses réglages, la déplacer ou la retirer.")),
            "it" to Entry("Impostazioni rapide", "Pagina 4: interruttori delle funzioni di sistema.", listOf("Predefiniti: Wi-Fi, Bluetooth e rotazione automatica. Tocca per cambiare; le schede attive si illuminano.", "“+” aggiunge modalità aereo, posizione, non disturbare, risparmio batteria, tema scuro e orizzontale forzato.", "Orizzontale forzato blocca lo schermo superiore in orizzontale, anche per le app verticali.", "Tieni premuta una scheda per aprirne le impostazioni, spostarla o rimuoverla.")),
            "zh" to Entry("快捷设置", "第 4 页：系统功能开关。", listOf("默认：Wi-Fi、蓝牙和自动旋转。点按切换，开启的图块会高亮。", "“+”可添加飞行模式、定位、勿扰、省电、深色主题和强制横屏。", "强制横屏会将上屏固定为横向，即使应用要求竖屏。", "长按图块可打开系统设置、移动或移除。"))
        )),
        Topic("keyboard", "keyboard", mapOf(
            "en" to Entry("PocketHub Keyboard", "On-screen keyboard on the lower screen.", listOf("Enable and select it in Settings → Keyboard. Choose languages, theme (including Retro keycaps), key size and the utility bar.", "Cartridge keyboard theme: the keyboard is a cartridge shell with a cut corner; keys are rubber console buttons that sink and light cream gold when pressed, Enter is cartridge red, function keys use a monospace console font. It matches the Cartridge interface design.", "Typewriter keyboard theme: round black keys in chrome rings on a dark green body, cream typewriter lettering and a ribbon-red Enter. Keys sink when pressed.", "Linea keyboard theme: no key boxes — letters float on a calm charcoal panel, each with a short underline. Function keys have a coral underline, Enter is a solid coral pill, and a pressed key lights up softly in coral.", "Page 2 → Keyboard opens it anytime, even without a text field: keys are typed into the top screen (needs root).", "Latin letters are typed as keys; Cyrillic, Chinese and emoji are pasted with Ctrl+V and your clipboard is restored.", "The utility bar has clipboard history, emoji, copy, cut and paste. Tap a text field on top to return to normal typing.")),
            "ru" to Entry("Клавиатура PocketHub", "Экранная клавиатура на нижнем экране.", listOf("Включи и выбери её в Настройки → Клавиатура. Там же языки, тема (в том числе «Ретро-клавиши»), размер клавиш и панель кнопок.", "Тема клавиатуры «Картридж»: клавиатура — корпус картриджа со срезанным углом, клавиши — резиновые кнопки приставки, которые при нажатии утапливаются и подсвечиваются кремовым золотом, Enter — красный, служебные клавиши моноширинным «консольным» шрифтом. Подходит к дизайну интерфейса «Картридж».", "Тема клавиатуры «Печатная машинка»: круглые чёрные клавиши в хромированных ободках на тёмно-зелёном корпусе, кремовые буквы шрифтом пишущей машинки и красная, как лента, клавиша Enter. Клавиши утапливаются при нажатии.", "Тема клавиатуры «Линия»: без рамок у клавиш — буквы лежат на спокойной графитовой панели, под каждой короткая черта. У служебных клавиш черта коралловая, Enter — сплошная коралловая «таблетка», нажатая клавиша мягко подсвечивается кораллом.", "Страница 2 → «Клавиатура» открывает её в любой момент, даже без текстового поля: ввод уходит на верхний экран (нужен root).", "Латиница печатается нажатиями клавиш; кириллица, китайский и эмодзи вставляются через Ctrl+V, буфер обмена потом восстанавливается.", "На панели — история буфера, эмодзи, копировать, вырезать и вставить. Нажми на поле ввода наверху, чтобы вернуться к обычному вводу.")),
            "nl" to Entry("PocketHub-toetsenbord", "Schermtoetsenbord op het onderste scherm.", listOf("Inschakelen en kiezen in Instellingen → Toetsenbord. Daar ook talen, thema (o.a. Retro-toetsen), toetsgrootte en hulpbalk.", "Toetsenbordthema Cartridge: het toetsenbord is een cartridgebehuizing met afgeschuinde hoek; toetsen zijn rubberen consoleknoppen die bij indrukken zakken en crèmegoud oplichten, Enter is cartridgerood, functietoetsen in een monospace consolelettertype. Past bij het ontwerp Cartridge.", "Toetsenbordthema Typemachine: ronde zwarte toetsen in chromen ringen op een donkergroene behuizing, crèmekleurige typemachineletters en een lintrode Enter. Toetsen zakken in bij indrukken.", "Toetsenbordthema Linea: geen toetsvakjes — letters zweven op een rustig antracietpaneel, elk met een korte onderstreping. Functietoetsen hebben een koraalrode streep, Enter is een koraalrode pil en een ingedrukte toets licht zacht op.", "Pagina 2 → Toetsenbord opent het altijd, ook zonder tekstveld: invoer gaat naar het bovenste scherm (root nodig).", "Latijnse letters worden als toetsen getypt; Cyrillisch, Chinees en emoji via Ctrl+V, je klembord wordt hersteld.", "De hulpbalk heeft klembordgeschiedenis, emoji, kopiëren, knippen en plakken. Tik op een tekstveld boven voor normaal typen.")),
            "es" to Entry("Teclado PocketHub", "Teclado en pantalla en la pantalla inferior.", listOf("Actívalo y selecciónalo en Ajustes → Teclado. Allí eliges idiomas, tema (incluido Teclas retro), tamaño y barra de acciones.", "Tema de teclado Cartucho: el teclado es una carcasa de cartucho con una esquina recortada; las teclas son botones de goma que se hunden y se iluminan en oro crema al pulsarlas, Enter es rojo cartucho y las teclas de función usan una fuente monoespaciada de consola. Combina con el diseño Cartucho.", "Tema de teclado Máquina de escribir: teclas negras redondas con aros cromados sobre un cuerpo verde oscuro, letras crema de máquina de escribir y un Enter rojo cinta. Las teclas se hunden al pulsarlas.", "Tema de teclado Línea: sin recuadros — las letras flotan sobre un panel grafito sereno, cada una con un breve subrayado. Las teclas de función tienen subrayado coral, Enter es una píldora coral y la tecla pulsada se ilumina suavemente.", "Página 2 → Teclado lo abre en cualquier momento, incluso sin campo de texto: escribe en la pantalla superior (requiere root).", "Las letras latinas se envían como teclas; cirílico, chino y emoji se pegan con Ctrl+V y se restaura tu portapapeles.", "La barra incluye historial del portapapeles, emoji, copiar, cortar y pegar. Toca un campo de texto arriba para volver al modo normal.")),
            "de" to Entry("PocketHub-Tastatur", "Bildschirmtastatur auf dem unteren Bildschirm.", listOf("In Einstellungen → Tastatur aktivieren und auswählen. Dort auch Sprachen, Design (inkl. Retro-Tasten), Tastengröße und Werkzeugleiste.", "Tastaturdesign Spielmodul: Die Tastatur ist ein Modulgehäuse mit abgeschrägter Ecke; Tasten sind Gummi-Konsolenknöpfe, die beim Drücken einsinken und cremegold leuchten, Enter ist modulrot, Funktionstasten in einer Monospace-Konsolenschrift. Passt zum Oberflächendesign Spielmodul.", "Tastaturdesign Schreibmaschine: runde schwarze Tasten in Chromringen auf dunkelgrünem Gehäuse, cremefarbene Schreibmaschinenschrift und eine farbbandrote Enter-Taste. Tasten sinken beim Drücken ein.", "Tastaturdesign Linea: keine Tastenkästen — Buchstaben schweben auf einer ruhigen anthrazitfarbenen Fläche, jeder mit einem kurzen Unterstrich. Funktionstasten haben einen korallfarbenen Strich, Enter ist eine korallfarbene Pille, gedrückte Tasten leuchten sanft auf.", "Seite 2 → Tastatur öffnet sie jederzeit, auch ohne Textfeld: Eingaben gehen auf den oberen Bildschirm (Root nötig).", "Lateinische Buchstaben werden als Tasten gesendet; Kyrillisch, Chinesisch und Emoji per Strg+V, die Zwischenablage wird wiederhergestellt.", "Die Leiste bietet Zwischenablage-Verlauf, Emoji, Kopieren, Ausschneiden und Einfügen. Tippe oben auf ein Textfeld für normales Tippen.")),
            "fr" to Entry("Clavier PocketHub", "Clavier à l'écran sur l'écran du bas.", listOf("Activez-le et choisissez-le dans Réglages → Clavier : langues, thème (dont Touches rétro), taille des touches et barre d'outils.", "Thème de clavier Cartouche : le clavier est une coque de cartouche à coin coupé ; les touches sont des boutons en caoutchouc qui s'enfoncent et s'éclairent en or crème, Entrée est rouge cartouche, les touches de fonction utilisent une police console à chasse fixe. Assorti au design Cartouche.", "Thème de clavier Machine à écrire : touches noires rondes cerclées de chrome sur un corps vert foncé, lettres crème façon machine à écrire et Entrée rouge ruban. Les touches s’enfoncent à l’appui.", "Thème de clavier Linea : pas de cases — les lettres flottent sur un panneau anthracite apaisé, chacune avec un court soulignement. Les touches de fonction ont un trait corail, Entrée est une pastille corail et la touche pressée s’allume doucement.", "Page 2 → Clavier l'ouvre à tout moment, même sans champ de texte : la saisie va à l'écran du haut (root requis).", "Les lettres latines sont envoyées comme touches ; cyrillique, chinois et emoji sont collés via Ctrl+V, le presse-papiers est restauré.", "La barre offre historique du presse-papiers, emoji, copier, couper et coller. Touchez un champ en haut pour revenir à la saisie normale.")),
            "it" to Entry("Tastiera PocketHub", "Tastiera su schermo nello schermo inferiore.", listOf("Attivala e sceglila in Impostazioni → Tastiera: lingue, tema (anche Tasti retro), dimensione tasti e barra strumenti.", "Tema tastiera Cartuccia: la tastiera è un guscio di cartuccia con un angolo tagliato; i tasti sono pulsanti in gomma che affondano e si illuminano d'oro crema, Invio è rosso cartuccia, i tasti funzione usano un font da console a spaziatura fissa. Si abbina al design Cartuccia.", "Tema tastiera Macchina da scrivere: tasti neri rotondi in anelli cromati su un corpo verde scuro, lettere crema da macchina da scrivere e Invio rosso nastro. I tasti affondano quando premuti.", "Tema tastiera Linea: niente riquadri — le lettere galleggiano su un pannello antracite, ognuna con una breve sottolineatura. I tasti funzione hanno una linea corallo, Invio è una pillola corallo e il tasto premuto si illumina dolcemente.", "Pagina 2 → Tastiera la apre sempre, anche senza campo di testo: scrive sullo schermo superiore (serve root).", "Le lettere latine sono inviate come tasti; cirillico, cinese ed emoji vengono incollati con Ctrl+V e gli appunti ripristinati.", "La barra offre cronologia appunti, emoji, copia, taglia e incolla. Tocca un campo di testo in alto per la digitazione normale.")),
            "zh" to Entry("PocketHub 键盘", "显示在下屏的屏幕键盘。", listOf("在 设置 → 键盘 中启用并选择。可设置语言、主题（含“复古键帽”）、按键大小和工具栏。", "键盘主题“卡带”：整个键盘是切角的卡带外壳；按键是橡胶主机按钮，按下时下沉并亮起奶油金色，回车为卡带红，功能键使用等宽主机字体。与界面设计“卡带”相配。", "键盘主题“打字机”：深绿色机身上带镀铬圈的圆形黑色按键，奶油色打字机字体，色带红的回车键。按下时按键会下沉。", "键盘主题“线条”：没有按键框——字母浮在沉稳的炭灰面板上，下方各有一条短线。功能键为珊瑚色短线，回车为珊瑚色胶囊，按下时柔和地亮起珊瑚色。", "第 2 页 →“键盘”可随时打开，即使没有输入框：输入发送到上屏（需要 root）。", "拉丁字母以按键方式输入；西里尔文、中文和表情通过 Ctrl+V 粘贴，之后恢复剪贴板。", "工具栏提供剪贴板历史、表情、复制、剪切和粘贴。点按上屏输入框即可恢复普通输入。"))
        )),
        Topic("touchpad", "touchpad", mapOf(
            "en" to Entry("Touchpad (mouse)", "A touchpad on the lower screen with a cursor on top.", listOf("One finger moves the cursor; faster strokes travel further.", "Tap = left click, two-finger tap or RIGHT = right click, two fingers up/down = scroll.", "Hold LEFT and move to drag: select text, scroll lists, move sliders. ✕ closes the touchpad.", "Needs root and “display over other apps”.")),
            "ru" to Entry("Тачпад (мышь)", "Тачпад на нижнем экране и курсор на верхнем.", listOf("Один палец двигает курсор; чем быстрее движение, тем дальше он уходит.", "Тап — левый клик, тап двумя пальцами или ПРАВАЯ — правый клик, два пальца вверх-вниз — прокрутка.", "Зажми ЛЕВАЯ и веди — перетаскивание: выделение текста, списки, ползунки. ✕ закрывает тачпад.", "Нужны root и разрешение «поверх других окон».")),
            "nl" to Entry("Touchpad (muis)", "Een touchpad onderaan met een cursor bovenaan.", listOf("Eén vinger beweegt de cursor; snellere bewegingen gaan verder.", "Tik = linkerklik, tik met twee vingers of RECHTS = rechterklik, twee vingers op/neer = scrollen.", "Houd LINKS vast en beweeg om te slepen: tekst selecteren, lijsten, schuifregelaars. ✕ sluit.", "Root en “weergeven over andere apps” nodig.")),
            "es" to Entry("Panel táctil (ratón)", "Un panel táctil abajo con un cursor arriba.", listOf("Un dedo mueve el cursor; los movimientos rápidos llegan más lejos.", "Toque = clic izquierdo, toque con dos dedos o DERECHO = clic derecho, dos dedos arriba/abajo = desplazar.", "Mantén IZQUIERDO y mueve para arrastrar: seleccionar texto, listas, deslizadores. ✕ lo cierra.", "Necesita root y “mostrar sobre otras apps”.")),
            "de" to Entry("Touchpad (Maus)", "Ein Touchpad unten mit Cursor oben.", listOf("Ein Finger bewegt den Cursor; schnelle Bewegungen gehen weiter.", "Tippen = Linksklick, Zwei-Finger-Tipp oder RECHTS = Rechtsklick, zwei Finger hoch/runter = Scrollen.", "LINKS halten und bewegen zum Ziehen: Text markieren, Listen, Regler. ✕ schließt.", "Root und „Über anderen Apps einblenden“ nötig.")),
            "fr" to Entry("Pavé tactile (souris)", "Un pavé tactile en bas, un curseur en haut.", listOf("Un doigt déplace le curseur ; les gestes rapides vont plus loin.", "Toucher = clic gauche, toucher à deux doigts ou DROIT = clic droit, deux doigts haut/bas = défilement.", "Maintenez GAUCHE et bougez pour glisser : sélection de texte, listes, curseurs. ✕ ferme.", "Nécessite root et « affichage par-dessus les autres apps ».")),
            "it" to Entry("Touchpad (mouse)", "Un touchpad in basso con cursore in alto.", listOf("Un dito muove il cursore; i movimenti rapidi vanno più lontano.", "Tocco = clic sinistro, tocco a due dita o DESTRO = clic destro, due dita su/giù = scorrimento.", "Tieni SINISTRO e muovi per trascinare: selezione testo, liste, cursori. ✕ chiude.", "Servono root e “mostra sopra altre app”.")),
            "zh" to Entry("触控板（鼠标）", "下屏为触控板，上屏显示光标。", listOf("单指移动光标；滑动越快移动越远。", "轻点 = 左键，双指轻点或“右键” = 右键，双指上下滑动 = 滚动。", "按住“左键”并移动即可拖动：选择文字、滚动列表、拖动滑块。✕ 关闭触控板。", "需要 root 和“显示在其他应用上层”权限。"))
        )),
        Topic("pckeyboard", "pc", mapOf(
            "en" to Entry("PC keyboard", "Full English computer layout on the lower screen.", listOf("Esc, F1–F12, number row with symbols, Tab, Caps, Enter, Ctrl, Win, Alt, arrows, Home, End, PgUp, PgDn, Ins, PrtSc.", "Modifiers are sticky: tap once for the next key (blue), twice to lock (orange), again to release. Shortcuts like Ctrl+C or Alt+Tab work.", "Backspace, Delete, arrows and page keys repeat while held. Keys go to the top screen (needs root).")),
            "ru" to Entry("PC-клавиатура", "Полная английская раскладка компьютера на нижнем экране.", listOf("Esc, F1–F12, цифры с символами, Tab, Caps, Enter, Ctrl, Win, Alt, стрелки, Home, End, PgUp, PgDn, Ins, PrtSc.", "Модификаторы залипают: одно нажатие — на следующую клавишу (синий), двойное — фиксация (оранжевый), ещё одно — снять. Работают Ctrl+C, Alt+Tab и т. п.", "Backspace, Delete, стрелки и PgUp/PgDn повторяются при удержании. Нажатия уходят на верхний экран (нужен root).")),
            "nl" to Entry("Pc-toetsenbord", "Volledige Engelse pc-indeling op het onderste scherm.", listOf("Esc, F1–F12, cijferrij met symbolen, Tab, Caps, Enter, Ctrl, Win, Alt, pijlen, Home, End, PgUp, PgDn, Ins, PrtSc.", "Modifiers blijven plakken: één tik voor de volgende toets (blauw), twee om te vergrendelen (oranje), nog eens om los te laten. Ctrl+C of Alt+Tab werken.", "Backspace, Delete, pijlen en paginatoetsen herhalen bij vasthouden. Toetsen gaan naar het bovenste scherm (root nodig).")),
            "es" to Entry("Teclado de PC", "Distribución completa de PC en inglés en la pantalla inferior.", listOf("Esc, F1–F12, fila numérica con símbolos, Tab, Caps, Enter, Ctrl, Win, Alt, flechas, Inicio, Fin, RePág, AvPág, Ins, ImprPant.", "Los modificadores se quedan pulsados: un toque para la siguiente tecla (azul), dos para fijar (naranja), otro para soltar. Funcionan Ctrl+C o Alt+Tab.", "Retroceso, Supr, flechas y teclas de página se repiten al mantener. Las teclas van a la pantalla superior (requiere root).")),
            "de" to Entry("PC-Tastatur", "Volles englisches PC-Layout auf dem unteren Bildschirm.", listOf("Esc, F1–F12, Zahlenreihe mit Symbolen, Tab, Caps, Enter, Strg, Win, Alt, Pfeile, Pos1, Ende, Bild↑, Bild↓, Einfg, Druck.", "Modifikatoren rasten ein: einmal tippen für die nächste Taste (blau), zweimal zum Sperren (orange), erneut zum Lösen. Strg+C oder Alt+Tab funktionieren.", "Rücktaste, Entf, Pfeile und Bildtasten wiederholen beim Halten. Eingaben gehen auf den oberen Bildschirm (Root nötig).")),
            "fr" to Entry("Clavier PC", "Disposition PC anglaise complète sur l'écran du bas.", listOf("Échap, F1–F12, rangée de chiffres avec symboles, Tab, Verr. maj, Entrée, Ctrl, Win, Alt, flèches, Début, Fin, PgPréc, PgSuiv, Inser, ImprÉcr.", "Les modificateurs restent enfoncés : un toucher pour la touche suivante (bleu), deux pour verrouiller (orange), encore pour relâcher. Ctrl+C ou Alt+Tab fonctionnent.", "Retour arrière, Suppr, flèches et touches de page se répètent au maintien. Les touches vont à l'écran du haut (root requis).")),
            "it" to Entry("Tastiera PC", "Layout PC inglese completo sullo schermo inferiore.", listOf("Esc, F1–F12, riga numerica con simboli, Tab, Bloc maiusc, Invio, Ctrl, Win, Alt, frecce, Home, Fine, PagSu, PagGiù, Ins, Stamp.", "I modificatori restano attivi: un tocco per il tasto successivo (blu), due per bloccare (arancione), ancora per rilasciare. Funzionano Ctrl+C o Alt+Tab.", "Backspace, Canc, frecce e tasti pagina si ripetono tenendo premuto. I tasti vanno allo schermo superiore (serve root).")),
            "zh" to Entry("电脑键盘", "下屏显示完整的英文电脑布局。", listOf("Esc、F1–F12、带符号的数字行、Tab、Caps、Enter、Ctrl、Win、Alt、方向键、Home、End、PgUp、PgDn、Ins、PrtSc。", "修饰键为粘滞模式：点一次作用于下一个键（蓝色），点两次锁定（橙色），再点取消。支持 Ctrl+C、Alt+Tab 等快捷键。", "退格、删除、方向键和翻页键长按会连发。按键发送到上屏（需要 root）。"))
        )),
        Topic("screens", "display", mapOf(
            "en" to Entry("Dual screen control", "Which screens are on and where input goes.", listOf("Open it with Dual screen at the bottom of the dashboard, or with a remapped button.", "Active display: both, top or bottom. Top screen input: cursor or touchpad on the lower screen.", "Controller focus: Auto follows the last touch; Top or Bottom locks control to one screen.", "From a button the window opens over the current app; pressing the button again closes it. If the lower screen is off, the AYANEO button turns it back on.")),
            "ru" to Entry("Управление двумя экранами", "Какие экраны включены и куда идёт ввод.", listOf("Открывается кнопкой «Два экрана» внизу главной или переназначенной кнопкой.", "Активный экран: оба, верхний или нижний. Управление верхним экраном: курсор или тачпад на нижнем.", "Фокус контроллера: «Авто» следует за последним касанием; «Верхний» или «Нижний» закрепляет управление.", "С кнопки окно появляется поверх текущей программы; повторное нажатие закрывает его. Если нижний экран выключен, кнопка AYANEO включит его снова.")),
            "nl" to Entry("Dubbel scherm-bediening", "Welke schermen aan staan en waar invoer heen gaat.", listOf("Open het via 2 schermen onderaan het dashboard of met een toegewezen knop.", "Actief scherm: beide, boven of onder. Invoer bovenscherm: cursor of touchpad op het onderste scherm.", "Controllerfocus: Auto volgt de laatste aanraking; Boven of Onder vergrendelt de bediening.", "Via een knop opent het venster boven de huidige app; nogmaals drukken sluit het. Is het onderste scherm uit, dan zet de AYANEO-knop het weer aan.")),
            "es" to Entry("Control de doble pantalla", "Qué pantallas están activas y adónde va la entrada.", listOf("Ábrelo con 2 pantallas en la parte inferior del panel o con un botón reasignado.", "Pantalla activa: ambas, superior o inferior. Entrada superior: cursor o panel táctil en la pantalla inferior.", "Enfoque del mando: Auto sigue el último toque; Superior o Inferior lo fija a una pantalla.", "Desde un botón la ventana aparece sobre la app actual; pulsarlo de nuevo la cierra. Si la pantalla inferior está apagada, el botón AYANEO la enciende.")),
            "de" to Entry("Zwei-Display-Steuerung", "Welche Displays an sind und wohin Eingaben gehen.", listOf("Öffnen über 2 Displays unten im Dashboard oder mit einer belegten Taste.", "Aktives Display: beide, oben oder unten. Eingabe oben: Cursor oder Touchpad auf dem unteren Display.", "Controllerfokus: Auto folgt der letzten Berührung; Oben oder Unten sperrt die Steuerung.", "Per Taste öffnet sich das Fenster über der aktuellen App; erneutes Drücken schließt es. Ist das untere Display aus, schaltet die AYANEO-Taste es wieder ein.")),
            "fr" to Entry("Contrôle des deux écrans", "Écrans actifs et destination des saisies.", listOf("Ouvrez-le avec 2 écrans en bas du tableau ou avec un bouton réassigné.", "Écran actif : les deux, haut ou bas. Saisie de l'écran du haut : curseur ou pavé tactile en bas.", "Focus de la manette : Auto suit le dernier toucher ; Haut ou Bas le verrouille.", "Depuis un bouton, la fenêtre s'ouvre sur l'app en cours ; un nouvel appui la ferme. Si l'écran du bas est éteint, le bouton AYANEO le rallume.")),
            "it" to Entry("Controllo doppio schermo", "Quali schermi sono attivi e dove va l'input.", listOf("Aprilo con 2 schermi in basso nel pannello o con un tasto riassegnato.", "Schermo attivo: entrambi, superiore o inferiore. Input superiore: cursore o touchpad sullo schermo inferiore.", "Focus del controller: Auto segue l'ultimo tocco; Superiore o Inferiore lo blocca.", "Da un tasto la finestra si apre sopra l'app attuale; premendolo di nuovo si chiude. Se lo schermo inferiore è spento, il tasto AYANEO lo riaccende.")),
            "zh" to Entry("双屏控制", "选择开启的屏幕和输入去向。", listOf("通过仪表盘底部的“双屏”或重新映射的按键打开。", "活动屏幕：双屏、上屏或下屏。上屏输入：下屏作为光标或触控板。", "手柄焦点：自动跟随最后触摸；上屏或下屏则锁定控制。", "用按键打开时窗口显示在当前应用上方，再按一次关闭。下屏关闭时，AYANEO 键可重新打开它。"))
        )),
        Topic("controller", "controller", mapOf(
            "en" to Entry("Controller", "Built-in gamepad: mode, vibration and button layout.", listOf("Page 2 → Controller.", "Controller mode: Xbox (XInput, best for most games and streaming) or AYANEO (DInput). The controller reconnects for a moment when you switch.", "Vibration: off, low, medium or high. Button layout: Xbox or Japanese (A/B and X/Y swapped).", "Game profiles can change layout and vibration per game and restore them when the game closes.")),
            "ru" to Entry("Контроллер", "Встроенный геймпад: режим, вибрация и раскладка.", listOf("Страница 2 → «Контроллер».", "Режим контроллера: Xbox (XInput — лучше для большинства игр и стриминга) или AYANEO (DInput). При переключении контроллер на миг переподключается.", "Вибрация: выкл., слабая, средняя или сильная. Раскладка: Xbox или японская (A/B и X/Y меняются местами).", "Игровые профили могут менять раскладку и вибрацию для каждой игры и возвращают их, когда игра закрывается.")),
            "nl" to Entry("Controller", "Ingebouwde gamepad: modus, trilling en knopindeling.", listOf("Pagina 2 → Controller.", "Controllermodus: Xbox (XInput, het beste voor de meeste games en streaming) of AYANEO (DInput). Bij wisselen maakt de controller kort opnieuw verbinding.", "Trilling: uit, laag, gemiddeld of hoog. Knopindeling: Xbox of Japans (A/B en X/Y gewisseld).", "Gameprofielen kunnen indeling en trilling per game wijzigen en zetten ze terug als de game sluit.")),
            "es" to Entry("Mando", "Mando integrado: modo, vibración y distribución.", listOf("Página 2 → Mando.", "Modo del mando: Xbox (XInput, lo mejor para la mayoría de juegos y streaming) o AYANEO (DInput). Al cambiar, el mando se reconecta un instante.", "Vibración: desactivada, baja, media o alta. Distribución: Xbox o japonesa (A/B y X/Y intercambiados).", "Los perfiles de juego pueden cambiar distribución y vibración por juego y las restauran al cerrarlo.")),
            "de" to Entry("Controller", "Eingebautes Gamepad: Modus, Vibration und Tastenbelegung.", listOf("Seite 2 → Controller.", "Controllermodus: Xbox (XInput, am besten für die meisten Spiele und Streaming) oder AYANEO (DInput). Beim Wechsel verbindet sich der Controller kurz neu.", "Vibration: aus, schwach, mittel oder stark. Belegung: Xbox oder japanisch (A/B und X/Y getauscht).", "Spielprofile können Belegung und Vibration pro Spiel ändern und stellen sie beim Schließen wieder her.")),
            "fr" to Entry("Manette", "Manette intégrée : mode, vibration et disposition.", listOf("Page 2 → Manette.", "Mode de la manette : Xbox (XInput, idéal pour la plupart des jeux et le streaming) ou AYANEO (DInput). La manette se reconnecte un instant lors du changement.", "Vibration : désactivée, faible, moyenne ou forte. Disposition : Xbox ou japonaise (A/B et X/Y inversés).", "Les profils de jeu peuvent changer disposition et vibration par jeu et les rétablissent à la fermeture.")),
            "it" to Entry("Controller", "Gamepad integrato: modalità, vibrazione e layout.", listOf("Pagina 2 → Controller.", "Modalità controller: Xbox (XInput, ideale per la maggior parte dei giochi e lo streaming) o AYANEO (DInput). Al cambio il controller si riconnette per un attimo.", "Vibrazione: spenta, bassa, media o alta. Layout: Xbox o giapponese (A/B e X/Y scambiati).", "I profili di gioco possono cambiare layout e vibrazione per gioco e li ripristinano alla chiusura.")),
            "zh" to Entry("手柄", "内置手柄：模式、震动和按键布局。", listOf("第 2 页 → 手柄。", "手柄模式：Xbox（XInput，适合大多数游戏和串流）或 AYANEO（DInput）。切换时手柄会短暂重新连接。", "震动：关、弱、中、强。按键布局：Xbox 或日式（A/B 与 X/Y 互换）。", "游戏配置可按游戏更改布局和震动，游戏关闭后自动恢复。"))
        )),
        Topic("buttons", "controller", mapOf(
            "en" to Entry("Button remapping", "Give the extra buttons new jobs.", listOf("Page 2 → Device → Buttons → “Add a button”, then press the button. Game buttons (ABXY, shoulders, sticks, D-pad, Start, Select) are ignored; the Home (guide) button can be remapped.", "Out of the box: Mode — screenshot of both screens; BUTTON_3 — Dual screen controls; BUTTON_4 — Back; BUTTON_5 — screenshot; BUTTON_7 — Back (long press: Home); BUTTON_8 — Quick profile switch. Change or remove any of them.", "Each button has a short, long and double press. Long = hold half a second; double = two presses within 0.3 s.", "Actions: Back, Home, Recent apps, Previous app, Notifications, Quick settings, Screenshot (both screens), Lock screen, Show / hide PocketHub, Next profile, Quick profile switch, Dual screen control, Launch an app, or Do nothing.", "Quick profile switch and Dual screen control open a small window over the current app; press the button again to close it.", "Works through the PocketHub accessibility service, no root needed. “Remove” returns the button to normal.")),
            "ru" to Entry("Переназначение кнопок", "Новые действия для дополнительных кнопок.", listOf("Страница 2 → «Устройство» → «Кнопки» → «Добавить кнопку», затем нажми нужную кнопку. Игровые кнопки (ABXY, бамперы, стики, крестовина, Start, Select) игнорируются; кнопку Home (guide) переназначить можно.", "Сразу после установки: Mode — снимок обоих экранов; BUTTON_3 — управление двумя экранами; BUTTON_4 — Назад; BUTTON_5 — снимок экрана; BUTTON_7 — Назад (долгое нажатие: Домой); BUTTON_8 — быстрая смена профиля. Любую можно поменять или убрать.", "У каждой кнопки есть короткое, длинное и двойное нажатие. Длинное — удержание полсекунды; двойное — два нажатия за 0,3 с.", "Действия: «Назад», «Домой», «Последние приложения», «Предыдущее приложение», «Уведомления», «Быстрые настройки», «Снимок обоих экранов», «Заблокировать экран», «Показать / скрыть PocketHub», «Следующий профиль», «Быстрая смена профиля», «Управление двумя экранами», «Запустить приложение» или «Ничего».", "«Быстрая смена профиля» и «Управление двумя экранами» открывают маленькое окно поверх текущего приложения; повторное нажатие кнопки закрывает его.", "Работает через службу специальных возможностей PocketHub, root не нужен. «Удалить» возвращает кнопке обычное поведение.")),
            "nl" to Entry("Knoppen toewijzen", "Geef de extra knoppen een nieuwe taak.", listOf("Pagina 2 → Apparaat → Knoppen → “Knop toevoegen”, druk dan op de knop. Gameknoppen (ABXY, schouders, sticks, D-pad, Start, Select) worden genegeerd; de Home-knop (guide) kan wel.", "Standaard: Mode — schermafbeelding van beide schermen; BUTTON_3 — Bediening twee schermen; BUTTON_4 — Terug; BUTTON_5 — schermafbeelding; BUTTON_7 — Terug (lang: Start); BUTTON_8 — Profiel snel wisselen. Elk is te wijzigen of te verwijderen.", "Elke knop heeft kort, lang en dubbel drukken. Lang = een halve seconde vasthouden; dubbel = twee keer binnen 0,3 s.", "Acties: Terug, Home, Recente apps, Vorige app, Meldingen, Snelle instellingen, Screenshot (beide schermen), Scherm vergrendelen, PocketHub tonen / verbergen, Volgend profiel, Snel profiel wisselen, Bediening twee schermen, App starten of Niets.", "Snel profiel wisselen en Bediening twee schermen openen een klein venster over de huidige app; nogmaals drukken sluit het.", "Werkt via de PocketHub-toegankelijkheidsservice, zonder root. “Verwijderen” zet de knop terug.")),
            "es" to Entry("Reasignar botones", "Nuevas funciones para los botones extra.", listOf("Página 2 → Dispositivo → Botones → “Añadir botón” y pulsa el botón. Los botones de juego (ABXY, gatillos, sticks, cruceta, Start, Select) se ignoran; el botón Home (guía) sí se puede reasignar.", "De fábrica: Mode — captura de ambas pantallas; BUTTON_3 — Control de doble pantalla; BUTTON_4 — Atrás; BUTTON_5 — captura; BUTTON_7 — Atrás (pulsación larga: Inicio); BUTTON_8 — Cambio rápido de perfil. Puedes cambiar o quitar cualquiera.", "Cada botón tiene pulsación corta, larga y doble. Larga = mantener medio segundo; doble = dos pulsaciones en 0,3 s.", "Acciones: Atrás, Inicio, Apps recientes, App anterior, Notificaciones, Ajustes rápidos, Captura (ambas pantallas), Bloquear pantalla, Mostrar / ocultar PocketHub, Perfil siguiente, Cambio rápido de perfil, Control de doble pantalla, Abrir una app o Nada.", "Cambio rápido de perfil y Control de doble pantalla abren una ventana pequeña sobre la app actual; pulsa el botón otra vez para cerrarla.", "Funciona con el servicio de accesibilidad de PocketHub, sin root. “Quitar” devuelve el botón a la normalidad.")),
            "de" to Entry("Tasten neu belegen", "Neue Aufgaben für die Zusatztasten.", listOf("Seite 2 → Gerät → Tasten → „Taste hinzufügen“, dann die Taste drücken. Spieltasten (ABXY, Schultertasten, Sticks, Steuerkreuz, Start, Select) werden ignoriert; die Home-Taste (Guide) lässt sich belegen.", "Ab Werk: Mode — Screenshot beider Bildschirme; BUTTON_3 — Zwei-Bildschirm-Steuerung; BUTTON_4 — Zurück; BUTTON_5 — Screenshot; BUTTON_7 — Zurück (lang: Start); BUTTON_8 — Schneller Profilwechsel. Jede lässt sich ändern oder entfernen.", "Jede Taste hat kurzen, langen und doppelten Druck. Lang = eine halbe Sekunde halten; doppelt = zweimal innerhalb von 0,3 s.", "Aktionen: Zurück, Home, Letzte Apps, Vorherige App, Benachrichtigungen, Schnelleinstellungen, Screenshot (beide Bildschirme), Bildschirm sperren, PocketHub ein-/ausblenden, Nächstes Profil, Schneller Profilwechsel, Zwei-Bildschirm-Steuerung, App starten oder Nichts.", "Schneller Profilwechsel und Zwei-Bildschirm-Steuerung öffnen ein kleines Fenster über der aktuellen App; erneutes Drücken schließt es.", "Läuft über den PocketHub-Bedienungshilfedienst, ohne Root. „Entfernen“ stellt die Taste wieder normal.")),
            "fr" to Entry("Réaffecter les boutons", "De nouvelles fonctions pour les boutons supplémentaires.", listOf("Page 2 → Appareil → Boutons → « Ajouter un bouton », puis appuyez sur le bouton. Les boutons de jeu (ABXY, gâchettes, sticks, croix, Start, Select) sont ignorés ; le bouton Home (guide) peut être réaffecté.", "Par défaut : Mode — capture des deux écrans ; BUTTON_3 — Contrôle double écran ; BUTTON_4 — Retour ; BUTTON_5 — capture ; BUTTON_7 — Retour (appui long : Accueil) ; BUTTON_8 — Changement rapide de profil. Chacun peut être modifié ou retiré.", "Chaque bouton a un appui court, long et double. Long = maintenir une demi-seconde ; double = deux appuis en 0,3 s.", "Actions : Retour, Accueil, Apps récentes, App précédente, Notifications, Réglages rapides, Capture (deux écrans), Verrouiller l’écran, Afficher / masquer PocketHub, Profil suivant, Changement rapide de profil, Contrôle des deux écrans, Lancer une app ou Rien.", "Changement rapide de profil et Contrôle des deux écrans ouvrent une petite fenêtre au-dessus de l’app ; un nouvel appui la ferme.", "Fonctionne via le service d’accessibilité de PocketHub, sans root. « Retirer » rend au bouton son rôle normal.")),
            "it" to Entry("Rimappare i pulsanti", "Nuove funzioni per i pulsanti extra.", listOf("Pagina 2 → Dispositivo → Pulsanti → “Aggiungi pulsante”, poi premi il pulsante. I pulsanti di gioco (ABXY, dorsali, stick, croce, Start, Select) vengono ignorati; il pulsante Home (guida) si può rimappare.", "Di serie: Mode — screenshot di entrambi gli schermi; BUTTON_3 — Controllo doppio schermo; BUTTON_4 — Indietro; BUTTON_5 — screenshot; BUTTON_7 — Indietro (pressione lunga: Home); BUTTON_8 — Cambio rapido profilo. Ognuno si può cambiare o rimuovere.", "Ogni pulsante ha pressione breve, lunga e doppia. Lunga = tenere mezzo secondo; doppia = due pressioni entro 0,3 s.", "Azioni: Indietro, Home, App recenti, App precedente, Notifiche, Impostazioni rapide, Screenshot (entrambi gli schermi), Blocca schermo, Mostra / nascondi PocketHub, Profilo successivo, Cambio rapido profilo, Controllo doppio schermo, Avvia un’app o Niente.", "Cambio rapido profilo e Controllo doppio schermo aprono una piccola finestra sopra l’app; premi di nuovo per chiuderla.", "Funziona tramite il servizio di accessibilità di PocketHub, senza root. “Rimuovi” riporta il pulsante alla normalità.")),
            "zh" to Entry("按键映射", "为额外按键分配新功能。", listOf("第 2 页 → 设备 → 按键 → “添加按键”，然后按下该键。游戏键（ABXY、肩键、摇杆、方向键、Start、Select）会被忽略；Home（导航）键可以映射。", "默认设置：Mode — 双屏截图；BUTTON_3 — 双屏控制；BUTTON_4 — 返回；BUTTON_5 — 截图；BUTTON_7 — 返回（长按：主页）；BUTTON_8 — 快速切换配置。均可更改或删除。", "每个按键都有短按、长按和双击。长按 = 按住半秒；双击 = 0.3 秒内按两次。", "动作：返回、主页、最近应用、上一个应用、通知、快捷设置、截图（双屏）、锁屏、显示 / 隐藏 PocketHub、下一个配置、快速切换配置、双屏控制、启动应用或无动作。", "快速切换配置和双屏控制会在当前应用上方打开小窗口；再按一次按键即可关闭。", "通过 PocketHub 无障碍服务工作，无需 root。“移除”恢复按键默认功能。"))
        )),
        Topic("device", "cpu", mapOf(
            "en" to Entry("Device settings", "Page 2 → Device: buttons, charging, Wi-Fi, external monitor and memory.", listOf("Fan while charging (screen off): keeps the fan running at the speed you choose while the device charges with the screen off.", "Turn off Wi-Fi when the screen is off: never, immediately or after a few minutes. Wi-Fi comes back when you turn the screen on. Needs the PocketHub accessibility service.", "External monitor (USB-C): “Handheld + monitor” keeps both screens on; “Monitor only” turns both handheld screens off while a monitor is connected.", "Monitor resolution: tap Refresh to see whether a monitor is connected, then pick a resolution from the list it supports, or Default. The picture disappears for a second while it switches.", "Memory: the swap file (see Swap & zRAM). Needs root.")),
            "ru" to Entry("Настройки устройства", "Страница 2 → «Устройство»: кнопки, зарядка, Wi-Fi, внешний монитор и память.", listOf("Вентилятор при зарядке (экран выключен): вентилятор работает на выбранной скорости, пока устройство заряжается с выключенным экраном.", "Выключать Wi-Fi при выключенном экране: никогда, сразу или через несколько минут. При включении экрана Wi-Fi возвращается. Нужна служба специальных возможностей PocketHub.", "Внешний монитор (USB-C): «Консоль + монитор» оставляет оба экрана включёнными; «Только монитор» гасит оба экрана консоли, пока монитор подключён.", "Разрешение монитора: нажми «Обновить», чтобы проверить подключение, затем выбери разрешение из поддерживаемых монитором или «По умолчанию». При переключении картинка на секунду пропадает.", "Память: файл подкачки (см. «Swap и zRAM»). Нужен root.")),
            "nl" to Entry("Apparaatinstellingen", "Pagina 2 → Apparaat: knoppen, opladen, wifi, externe monitor en geheugen.", listOf("Ventilator tijdens opladen (scherm uit): de ventilator draait op de gekozen snelheid terwijl het apparaat met het scherm uit oplaadt.", "Wifi uit als het scherm uit is: nooit, direct of na een paar minuten. Wifi komt terug als je het scherm aanzet. Vereist de PocketHub-toegankelijkheidsservice.", "Externe monitor (USB-C): “Console + monitor” houdt beide schermen aan; “Alleen monitor” zet beide consoleschermen uit zolang er een monitor is aangesloten.", "Monitorresolutie: tik op Vernieuwen om te zien of er een monitor is, kies dan een ondersteunde resolutie of Standaard. Het beeld valt een seconde weg bij het wisselen.", "Geheugen: het swapbestand (zie Swap en zRAM). Vereist root.")),
            "es" to Entry("Ajustes del dispositivo", "Página 2 → Dispositivo: botones, carga, wifi, monitor externo y memoria.", listOf("Ventilador al cargar (pantalla apagada): el ventilador gira a la velocidad elegida mientras el dispositivo carga con la pantalla apagada.", "Apagar wifi con la pantalla apagada: nunca, al instante o tras unos minutos. El wifi vuelve al encender la pantalla. Requiere el servicio de accesibilidad de PocketHub.", "Monitor externo (USB-C): “Consola + monitor” mantiene ambas pantallas encendidas; “Solo monitor” apaga las dos pantallas de la consola mientras haya un monitor conectado.", "Resolución del monitor: pulsa Actualizar para ver si hay monitor y elige una resolución compatible o Predeterminada. La imagen desaparece un segundo al cambiar.", "Memoria: el archivo swap (ver Swap y zRAM). Requiere root.")),
            "de" to Entry("Geräteeinstellungen", "Seite 2 → Gerät: Tasten, Laden, WLAN, externer Monitor und Speicher.", listOf("Lüfter beim Laden (Bildschirm aus): Der Lüfter läuft mit der gewählten Drehzahl, während das Gerät mit ausgeschaltetem Bildschirm lädt.", "WLAN aus bei ausgeschaltetem Bildschirm: nie, sofort oder nach einigen Minuten. Beim Einschalten des Bildschirms kehrt WLAN zurück. Benötigt den PocketHub-Bedienungshilfedienst.", "Externer Monitor (USB-C): „Konsole + Monitor“ lässt beide Bildschirme an; „Nur Monitor“ schaltet beide Konsolenbildschirme aus, solange ein Monitor angeschlossen ist.", "Monitorauflösung: Aktualisieren prüft, ob ein Monitor angeschlossen ist; dann eine unterstützte Auflösung oder Standard wählen. Beim Umschalten ist das Bild kurz weg.", "Speicher: die Swap-Datei (siehe Swap und zRAM). Benötigt Root.")),
            "fr" to Entry("Réglages de l’appareil", "Page 2 → Appareil : boutons, charge, Wi-Fi, moniteur externe et mémoire.", listOf("Ventilateur en charge (écran éteint) : le ventilateur tourne à la vitesse choisie pendant la charge écran éteint.", "Couper le Wi-Fi écran éteint : jamais, immédiatement ou après quelques minutes. Le Wi-Fi revient à l’allumage de l’écran. Nécessite le service d’accessibilité de PocketHub.", "Moniteur externe (USB-C) : « Console + moniteur » garde les deux écrans allumés ; « Moniteur seul » éteint les deux écrans de la console tant qu’un moniteur est branché.", "Résolution du moniteur : Actualiser vérifie la connexion, puis choisissez une résolution prise en charge ou Par défaut. L’image disparaît une seconde pendant le changement.", "Mémoire : le fichier swap (voir Swap et zRAM). Nécessite root.")),
            "it" to Entry("Impostazioni dispositivo", "Pagina 2 → Dispositivo: pulsanti, ricarica, Wi-Fi, monitor esterno e memoria.", listOf("Ventola in ricarica (schermo spento): la ventola gira alla velocità scelta mentre il dispositivo si ricarica a schermo spento.", "Spegni il Wi-Fi a schermo spento: mai, subito o dopo alcuni minuti. Il Wi-Fi torna quando riaccendi lo schermo. Richiede il servizio di accessibilità di PocketHub.", "Monitor esterno (USB-C): “Console + monitor” lascia accesi entrambi gli schermi; “Solo monitor” spegne entrambi gli schermi della console finché è collegato un monitor.", "Risoluzione monitor: Aggiorna verifica il collegamento, poi scegli una risoluzione supportata o Predefinita. L’immagine sparisce per un secondo durante il cambio.", "Memoria: il file di swap (vedi Swap e zRAM). Richiede root.")),
            "zh" to Entry("设备设置", "第 2 页 → 设备：按键、充电、Wi-Fi、外接显示器和内存。", listOf("充电时风扇（息屏）：设备息屏充电时，风扇以所选速度运转。", "息屏时关闭 Wi-Fi：从不、立即或几分钟后。亮屏后 Wi-Fi 自动恢复。需要 PocketHub 无障碍服务。", "外接显示器（USB-C）：“掌机 + 显示器”保持两块屏幕开启；“仅显示器”在连接显示器时关闭掌机的两块屏幕。", "显示器分辨率：点击“刷新”检查是否已连接，然后从显示器支持的分辨率中选择，或选“默认”。切换时画面会消失一秒。", "内存：swap 文件（见 Swap 与 zRAM）。需要 root。"))
        )),
        Topic("media", "brightness", mapOf(
            "en" to Entry("Brightness & screenshots", "Dashboard bottom bar.", listOf("Brightness is set separately for each screen, from 1 % to 100 % — it never goes fully dark, so you can always turn it back up.", "Capture takes both screens at once; then choose to save the top, bottom or both. Nothing from PocketHub appears in the shot.", "A remapped button can take the same screenshot over any app.")),
            "ru" to Entry("Яркость и снимки экрана", "Нижняя панель главного экрана.", listOf("Яркость задаётся отдельно для каждого экрана, от 1 % до 100 % — экран никогда не гаснет полностью, поэтому яркость всегда можно вернуть.", "«Снимок» снимает оба экрана сразу; затем выбери, сохранить верхний, нижний или оба. Ничего от PocketHub на снимок не попадает.", "Переназначенная кнопка делает такой же снимок поверх любого приложения.")),
            "nl" to Entry("Helderheid en screenshots", "Onderste balk van het dashboard.", listOf("Helderheid stel je per scherm in, van 1 % tot 100 % — het scherm wordt nooit helemaal donker, zodat je het altijd terug kunt zetten.", "Foto legt beide schermen tegelijk vast; kies daarna boven, onder of beide. Niets van PocketHub komt in beeld.", "Een toegewezen knop maakt dezelfde screenshot boven elke app.")),
            "es" to Entry("Brillo y capturas", "Barra inferior del panel.", listOf("El brillo se ajusta por pantalla, del 1 % al 100 %: nunca se apaga del todo, así siempre puedes subirlo.", "Foto captura ambas pantallas a la vez; luego elige guardar la superior, la inferior o ambas. Nada de PocketHub aparece en la captura.", "Un botón reasignado hace la misma captura sobre cualquier app.")),
            "de" to Entry("Helligkeit und Screenshots", "Untere Leiste des Dashboards.", listOf("Die Helligkeit wird pro Bildschirm eingestellt, von 1 % bis 100 % — er wird nie ganz dunkel, so lässt sie sich immer wieder erhöhen.", "Foto nimmt beide Bildschirme gleichzeitig auf; dann oben, unten oder beide speichern. Nichts von PocketHub ist im Bild.", "Eine neu belegte Taste macht denselben Screenshot über jeder App.")),
            "fr" to Entry("Luminosité et captures", "Barre du bas du tableau.", listOf("La luminosité se règle par écran, de 1 % à 100 % — l’écran ne devient jamais tout noir, vous pouvez donc toujours la remonter.", "Capture prend les deux écrans à la fois ; choisissez ensuite d’enregistrer le haut, le bas ou les deux. Rien de PocketHub n’apparaît.", "Un bouton réaffecté fait la même capture au-dessus de n’importe quelle app.")),
            "it" to Entry("Luminosità e screenshot", "Barra in basso del pannello.", listOf("La luminosità si regola per ogni schermo, dall’1 % al 100 % — lo schermo non diventa mai del tutto nero, così puoi sempre rialzarla.", "Foto cattura entrambi gli schermi insieme; poi scegli di salvare il superiore, l’inferiore o entrambi. Niente di PocketHub compare nello scatto.", "Un pulsante rimappato fa lo stesso screenshot sopra qualsiasi app.")),
            "zh" to Entry("亮度与截图", "仪表盘底栏。", listOf("每块屏幕的亮度可单独调节，范围 1 %–100 % —— 屏幕永远不会完全变黑，随时都能调回来。", "截图会同时截取两块屏幕，然后选择保存上屏、下屏或两者。PocketHub 的界面不会出现在截图中。", "映射的按键可在任何应用上方截取同样的截图。"))
        )),
        Topic("sound", "dnd", mapOf(
            "en" to Entry("Sound & volume buttons", "Volume per screen and PocketHub's own volume panel.", listOf("Sound (dashboard) → “Separate volume per screen”: overall, upper and lower screen sliders. The status line shows which apps play on which screen and which can't be controlled.", "Settings → Audio → Volume keys → PocketHub panel replaces Android's volume popup with overall / upper / lower bars.", "Choose where the panel appears (upper, lower or both screens) and what the buttons change by default. Tap a row's name to switch for now; hold a button to change quickly.", "Some games output sound in a way per-app volume can't reach; the status line then lists them.")),
            "ru" to Entry("Звук и кнопки громкости", "Громкость по экранам и своя панель громкости.", listOf("«Звук» на главной → «Отдельная громкость по экранам»: общая громкость, верхний и нижний экран. Строка состояния показывает, что где играет и что нельзя регулировать.", "Настройки → Звук → Кнопки громкости → «Панель PocketHub» заменяет окно громкости Android полосками «Общая / Верхний / Нижний».", "Выбери, где показывать панель (верхний, нижний или оба экрана) и что кнопки меняют по умолчанию. Нажми на название строки, чтобы временно переключиться; удерживай кнопку для быстрой регулировки.", "Некоторые игры выводят звук так, что громкость приложения не регулируется; строка состояния их покажет.")),
            "nl" to Entry("Geluid en volumeknoppen", "Volume per scherm en een eigen volumepaneel.", listOf("Geluid (dashboard) → “Apart volume per scherm”: totaal, boven- en onderscherm. De statusregel toont welke apps waar spelen en welke niet te regelen zijn.", "Instellingen → Geluid → Volumeknoppen → PocketHub-paneel vervangt de volumepop-up van Android door balken totaal / boven / onder.", "Kies waar het paneel verschijnt (boven, onder of beide) en wat de knoppen standaard regelen. Tik op een regel om tijdelijk te wisselen; houd een knop vast voor snel regelen.", "Sommige games geven geluid zo weer dat app-volume ze niet bereikt; de statusregel toont ze.")),
            "es" to Entry("Sonido y botones de volumen", "Volumen por pantalla y panel de volumen propio.", listOf("Sonido (panel) → “Volumen separado por pantalla”: general, superior e inferior. La línea de estado muestra qué suena en cada pantalla y qué no se puede controlar.", "Ajustes → Audio → Botones de volumen → Panel PocketHub sustituye la ventana de volumen de Android por barras general / superior / inferior.", "Elige dónde aparece el panel (superior, inferior o ambas) y qué cambian los botones por defecto. Toca el nombre de una fila para cambiar por ahora; mantén el botón para ir rápido.", "Algunos juegos emiten sonido de forma que el volumen por app no los alcanza; la línea de estado los indica.")),
            "de" to Entry("Ton und Lautstärketasten", "Lautstärke pro Display und eigenes Lautstärkefeld.", listOf("Ton (Dashboard) → „Lautstärke pro Display getrennt“: gesamt, oben und unten. Die Statuszeile zeigt, was wo spielt und was nicht regelbar ist.", "Einstellungen → Audio → Lautstärketasten → PocketHub-Feld ersetzt das Android-Lautstärkefenster durch Balken gesamt / oben / unten.", "Wähle, wo das Feld erscheint (oben, unten oder beide) und was die Tasten standardmäßig ändern. Tippe auf eine Zeile zum vorübergehenden Wechsel; Taste halten für schnelles Regeln.", "Manche Spiele geben Ton so aus, dass die App-Lautstärke sie nicht erreicht; die Statuszeile nennt sie.")),
            "fr" to Entry("Son et boutons de volume", "Volume par écran et panneau de volume propre.", listOf("Son (tableau) → « Volume séparé par écran » : global, haut et bas. La ligne d'état montre ce qui joue sur chaque écran et ce qui n'est pas réglable.", "Réglages → Audio → Boutons de volume → Panneau PocketHub remplace la fenêtre de volume Android par des barres global / haut / bas.", "Choisissez où le panneau apparaît (haut, bas ou les deux) et ce que les boutons règlent par défaut. Touchez le nom d'une ligne pour changer temporairement ; maintenez le bouton pour aller vite.", "Certains jeux sortent le son d'une façon que le volume par app n'atteint pas ; la ligne d'état les indique.")),
            "it" to Entry("Audio e tasti volume", "Volume per schermo e pannello volume proprio.", listOf("Audio (pannello) → “Volume separato per schermo”: generale, superiore e inferiore. La riga di stato mostra cosa suona dove e cosa non è regolabile.", "Impostazioni → Audio → Tasti volume → Pannello PocketHub sostituisce la finestra volume di Android con barre generale / superiore / inferiore.", "Scegli dove appare il pannello (superiore, inferiore o entrambi) e cosa cambiano i tasti di default. Tocca il nome di una riga per cambiare al momento; tieni premuto per regolare in fretta.", "Alcuni giochi emettono l'audio in modo che il volume per app non li raggiunga; la riga di stato li elenca.")),
            "zh" to Entry("声音与音量键", "分屏音量和 PocketHub 音量面板。", listOf("仪表盘“声音” → “按屏幕分别调节音量”：总音量、上屏、下屏。状态行显示哪些应用在哪块屏幕播放、哪些无法调节。", "设置 → 声音 → 音量键 → PocketHub 面板，用总音量 / 上屏 / 下屏滑条替代 Android 音量弹窗。", "可选择面板显示位置（上屏、下屏或双屏）以及按键默认调节的项目。点按某一行名称可临时切换；按住按键可快速调节。", "有些游戏的声音输出方式无法按应用调节音量，状态行会列出它们。"))
        )),
        Topic("equalizer", "mixer", mapOf(
            "en" to Entry("Equalizer", "Shapes the sound of everything on the device.", listOf("Page 2 → Equalizer. Switch it on, pick Flat or a built-in preset, or move each band.", "Gain brings back loudness (the system equalizer lowers it); a limiter keeps it from distorting. Bass adds low end.", "Turning it on while music plays pauses the song for a moment so the effect applies straight away.", "Game profiles can have their own equalizer. While it is on, a notification keeps it running; it starts again after a reboot.")),
            "ru" to Entry("Эквалайзер", "Меняет звучание всего, что играет на устройстве.", listOf("Страница 2 → «Эквалайзер». Включи его, выбери «Ровно» или встроенный пресет либо двигай каждую полосу.", "«Усиление» возвращает громкость (системный эквалайзер её снижает); лимитер не даёт звуку искажаться. «Басы» добавляют низы.", "Если включить его во время музыки, песня на мгновение встанет на паузу, чтобы эффект применился сразу.", "У профилей игр может быть свой эквалайзер. Пока он включён, уведомление держит его в работе; после перезагрузки он включается сам.")),
            "nl" to Entry("Equalizer", "Past het geluid van alles op het apparaat aan.", listOf("Pagina 2 → Equalizer. Zet hem aan, kies Vlak of een ingebouwde preset, of verschuif elke band.", "Versterking brengt het volume terug (de systeemequalizer verlaagt het); een limiter voorkomt vervorming. Bas voegt laag toe.", "Aanzetten terwijl muziek speelt pauzeert het nummer even, zodat het effect direct werkt.", "Gameprofielen kunnen een eigen equalizer hebben. Een melding houdt hem actief; na een herstart start hij weer.")),
            "es" to Entry("Ecualizador", "Ajusta el sonido de todo el dispositivo.", listOf("Página 2 → Ecualizador. Actívalo, elige Plano o un preajuste, o mueve cada banda.", "Ganancia recupera el volumen (el ecualizador del sistema lo baja); un limitador evita la distorsión. Graves añade bajos.", "Activarlo con música sonando pausa la canción un instante para que el efecto se aplique al momento.", "Los perfiles de juego pueden tener su propio ecualizador. Una notificación lo mantiene activo; vuelve tras reiniciar.")),
            "de" to Entry("Equalizer", "Formt den Klang von allem auf dem Gerät.", listOf("Seite 2 → Equalizer. Einschalten, Flach oder ein eingebautes Preset wählen oder jedes Band verschieben.", "Verstärkung holt die Lautstärke zurück (der System-Equalizer senkt sie); ein Limiter verhindert Verzerrung. Bass fügt Tiefen hinzu.", "Beim Einschalten während Musik läuft pausiert der Titel kurz, damit der Effekt sofort greift.", "Spielprofile können einen eigenen Equalizer haben. Eine Benachrichtigung hält ihn aktiv; nach einem Neustart startet er wieder.")),
            "fr" to Entry("Égaliseur", "Modèle le son de tout l'appareil.", listOf("Page 2 → Égaliseur. Activez-le, choisissez Plat ou un préréglage, ou réglez chaque bande.", "Gain rétablit le volume (l'égaliseur système le baisse) ; un limiteur évite la distorsion. Basses ajoute du grave.", "L'activer pendant la musique met le morceau en pause un instant pour appliquer l'effet tout de suite.", "Les profils de jeu peuvent avoir leur égaliseur. Une notification le maintient actif ; il redémarre après un redémarrage.")),
            "it" to Entry("Equalizzatore", "Modella il suono di tutto il dispositivo.", listOf("Pagina 2 → Equalizzatore. Attivalo, scegli Piatto o un preset, oppure sposta ogni banda.", "Guadagno recupera il volume (l'equalizzatore di sistema lo abbassa); un limitatore evita la distorsione. Bassi aggiunge gravi.", "Attivarlo con musica in riproduzione mette in pausa il brano un istante per applicare subito l'effetto.", "I profili di gioco possono avere il loro equalizzatore. Una notifica lo mantiene attivo; riparte dopo il riavvio.")),
            "zh" to Entry("均衡器", "调整设备上所有声音。", listOf("第 2 页 → 均衡器。打开后选择“平坦”或内置预设，或调节每个频段。", "“增益”可找回音量（系统均衡器会降低音量）；限幅器防止失真。“低音”增强低频。", "在播放音乐时开启，歌曲会短暂暂停，以便效果立即生效。", "游戏配置可拥有自己的均衡器。开启期间由通知保持运行；重启后自动恢复。"))
        )),
        Topic("memory", "ram", mapOf(
            "en" to Entry("Swap & zRAM", "Extra virtual memory on storage.", listOf("Page 2 → Device → Memory adds a swap file of 1–16 GB; it is re-enabled after every boot.", "Large files take a few minutes to prepare on F2FS — PocketHub shows the progress.", "Swap is slower than RAM and does not add physical memory. The memory card shows only the swap file; zRAM (compressed RAM) is separate.")),
            "ru" to Entry("Swap и zRAM", "Дополнительная виртуальная память на накопителе.", listOf("Страница 2 → «Устройство» → «Память»: файл подкачки от 1 до 16 ГБ; он включается снова после каждой перезагрузки.", "Большие файлы на F2FS готовятся несколько минут — PocketHub показывает прогресс.", "Swap медленнее RAM и не добавляет физической памяти. Карточка памяти показывает только файл подкачки; zRAM (сжатая RAM) — отдельно.")),
            "nl" to Entry("Swap en zRAM", "Extra virtueel geheugen op de opslag.", listOf("Pagina 2 → Apparaat → Geheugen voegt een swapbestand van 1–16 GB toe; het wordt na elke herstart weer ingeschakeld.", "Grote bestanden hebben op F2FS een paar minuten nodig — PocketHub toont de voortgang.", "Swap is trager dan RAM en voegt geen fysiek geheugen toe. De geheugenkaart toont alleen het swapbestand; zRAM (gecomprimeerd RAM) staat los.")),
            "es" to Entry("Swap y zRAM", "Memoria virtual extra en el almacenamiento.", listOf("Página 2 → Dispositivo → Memoria añade un archivo swap de 1–16 GB; se reactiva tras cada reinicio.", "Los archivos grandes tardan unos minutos en prepararse en F2FS; PocketHub muestra el progreso.", "El swap es más lento que la RAM y no añade memoria física. La tarjeta de memoria solo muestra el archivo swap; zRAM (RAM comprimida) es aparte.")),
            "de" to Entry("Swap und zRAM", "Zusätzlicher virtueller Speicher auf dem Laufwerk.", listOf("Seite 2 → Gerät → Speicher legt eine Swap-Datei von 1–16 GB an; sie wird nach jedem Neustart wieder aktiviert.", "Große Dateien brauchen auf F2FS einige Minuten — PocketHub zeigt den Fortschritt.", "Swap ist langsamer als RAM und erhöht den physischen Speicher nicht. Die Speicherkarte zeigt nur die Swap-Datei; zRAM (komprimierter RAM) ist getrennt.")),
            "fr" to Entry("Swap et zRAM", "Mémoire virtuelle supplémentaire sur le stockage.", listOf("Page 2 → Appareil → Mémoire ajoute un fichier swap de 1 à 16 Go ; il est réactivé après chaque redémarrage.", "Les gros fichiers prennent quelques minutes sur F2FS — PocketHub affiche la progression.", "Le swap est plus lent que la RAM et n’ajoute pas de mémoire physique. La carte mémoire n’affiche que le fichier swap ; la zRAM (RAM compressée) est à part.")),
            "it" to Entry("Swap e zRAM", "Memoria virtuale extra sull’archiviazione.", listOf("Pagina 2 → Dispositivo → Memoria aggiunge un file di swap da 1 a 16 GB; viene riattivato a ogni riavvio.", "I file grandi richiedono qualche minuto su F2FS — PocketHub mostra l’avanzamento.", "Lo swap è più lento della RAM e non aggiunge memoria fisica. La scheda memoria mostra solo il file di swap; la zRAM (RAM compressa) è separata.")),
            "zh" to Entry("Swap 与 zRAM", "在存储上增加虚拟内存。", listOf("第 2 页 → 设备 → 内存：添加 1–16 GB 的 swap 文件，每次开机后自动重新启用。", "在 F2FS 上准备大文件需要几分钟 —— PocketHub 会显示进度。", "Swap 比内存慢，也不会增加物理内存。内存卡片只显示 swap 文件；zRAM（压缩内存）另行计算。"))
        )),
        Topic("themes", "dark", mapOf(
            "en" to Entry("Themes & appearance", "Change the whole look, not just colours.", listOf("Settings → Interface → Design: Aurora Live (default), Dusk, Obsidian, Cartridge, Deep Sea, Hi-Fi Deck, Hologram, Bauhaus, Jade, Glass, Compact, Neon, Solstice, Synthwave, Volcanic, 8-Bit, Neo-Brutal light and dark.", "Obsidian: near-black graphite with slow flowing lines, electric lime and blue accents, its own set of geometric animated icons, larger bottom buttons and its own sliders.", "Cartridge: retro gaming in a modern cut. Charcoal console plastic with cartridge red and cream gold. Cards are cartridge shells with a cut corner, a darker lip underneath and label stripes; buttons are rubber console keys; icons are modern pixel art on key tiles; headings use a monospace console font. Only the fan icon moves, and only while the fan spins. Profiles stay at the top. The touchpad and PC keyboard use the same style.", "Deep Sea: dark water lit from within. Near-black navy with turquoise and violet light; profiles keep their own bright colours. Cards are deep panes with a soft glow in one corner and a light line along the top, buttons are smooth capsules (turquoise-to-violet when active), icons sit in glass bubbles. Only the fan icon moves. Touchpad and PC keyboard match.", "Hi-Fi Deck: an 80s stereo component. Brushed dark metal with an orange-red stripe band, amber and teal display light. Cards are front panels with a bevel, corner screws and a status LED; buttons are hard keys that light up; sliders are LED level meters with a mixing-desk fader; the FPS chart is a spectrum analyser; icons sit in small display windows. Only the fan icon moves. Touchpad and PC keyboard match.", "Hologram: a projected head-up display. Cyan light on black over a faint hexagon lattice, amber for highlights. Panels have cut corners instead of rounded ones, with bright brackets and data ticks; buttons are slanted plates; sliders are rulers with a diamond knob; icons sit in hexagons; headings use readout lettering. The dashboard is arranged like a cockpit: readouts on top, the profile selector at the bottom. Only the fan icon moves. Touchpad and PC keyboard match.", "Bauhaus: bold geometric design. Black and off-white with the three primaries — yellow, red, blue. Flat square blocks with no rounding at all; coloured cards carry a solid quarter circle and a thick bar; buttons are square blocks with heavy edges; sliders are a square bar with a round red knob; icons are geometric tiles; headings are set in heavy black capitals. Only the fan icon moves. Touchpad and PC keyboard match.", "Jade: deep forest green with jade and pale lime light over faint map contours. Panels and buttons are leaf-shaped (big rounding on two opposite corners) with a thin vein of colour; sliders have a leaf-shaped knob; a completely new duotone icon set sits on leaf tiles. Only the fan icon moves, and only while it spins. Touchpad and PC keyboard match.", "Colour accent appears only for Glass, Compact and Neon; the other designs bring their own palette.", "Aurora, Dusk and Obsidian use animated icons. In Cartridge, Deep Sea, Hi-Fi Deck, Hologram, Bauhaus and Jade only the fan icon moves.", "Touchpad and PC keyboard follow Aurora, Dusk, Obsidian, Cartridge, Deep Sea, Hi-Fi Deck, Hologram, Bauhaus, Jade and Neo-Brutal. Keyboard themes are in Settings → Dual-screen keyboard.")),
            "ru" to Entry("Темы и внешний вид", "Меняется весь вид, а не только цвета.", listOf("Настройки → Интерфейс → Дизайн: «Живая аврора» (по умолчанию), «Сумерки», «Обсидиан», «Картридж», «Глубина», «Хай-Фай», «Голограмма», «Баухаус», «Нефрит», «Стекло», «Компактный», «Неоновая консоль», «Солнцестояние», «Синтвейв», «Вулкан», «8-битная консоль», «Необрутализм» светлый и тёмный.", "«Обсидиан»: почти чёрный графит с медленно текущими линиями, акценты — электрический лайм и синий, свой набор геометрических анимированных иконок, увеличенные нижние кнопки и свои ползунки.", "«Картридж»: ретро-гейминг в современном исполнении. Тёмный «консольный» пластик, красный картриджа и кремовое золото. Карточки — корпуса картриджей со срезанным углом, тёмной кромкой снизу и полосками-наклейками; кнопки — резиновые клавиши приставки; иконки — современный пиксель-арт на плитках-клавишах; заголовки моноширинным шрифтом, как в меню консоли. Двигается только иконка вентилятора, и только пока он крутится. Профили наверху. Тачпад и PC-клавиатура в том же стиле.", "«Глубина»: тёмная вода, подсвеченная изнутри. Почти чёрный синий с бирюзовым и фиолетовым светом; у профилей свои яркие цвета. Карточки — глубокие панели с мягким свечением в углу и светлой линией по верхнему краю, кнопки — гладкие капсулы (активные с переходом от бирюзового к фиолетовому), иконки — в стеклянных пузырях. Двигается только иконка вентилятора. Тачпад и PC-клавиатура в том же стиле.", "«Хай-Фай»: стереосистема 80-х. Тёмный шлифованный металл с полосой оранжево-красных цветов, янтарный и бирюзовый свет дисплеев. Карточки — передние панели с фаской, винтами по углам и светодиодом; кнопки — твёрдые клавиши, которые загораются; ползунки — светодиодные индикаторы уровня с фейдером, как на микшерном пульте; график FPS — спектроанализатор; иконки — в маленьких окошках-дисплеях. Двигается только иконка вентилятора. Тачпад и PC-клавиатура в том же стиле.", "«Голограмма»: проекционный дисплей, как в кабине. Бирюзовый свет на чёрном поверх едва заметной сетки шестиугольников, янтарный для выделения. У панелей срезанные углы вместо скруглённых, яркие скобы и риски данных; кнопки — наклонные пластины; ползунки — линейки с ромбом-бегунком; иконки — в шестиугольниках; заголовки шрифтом индикаторов. Главный экран устроен как кабина: показания сверху, выбор профиля внизу. Двигается только иконка вентилятора. Тачпад и PC-клавиатура в том же стиле.", "«Баухаус»: смелая геометрия. Чёрный и тёплый белый с тремя основными цветами — жёлтым, красным, синим. Плоские квадратные блоки без скруглений; на цветных карточках сплошная четверть круга и толстая полоса; кнопки — квадратные блоки с жирной рамкой; ползунки — квадратная полоса с круглым красным бегунком; иконки — геометрические плитки; заголовки — жирные чёрные заглавные. Двигается только иконка вентилятора. Тачпад и PC-клавиатура в том же стиле.", "«Нефрит»: глубокий лесной зелёный с нефритовым и бледно-салатовым светом поверх едва заметных линий рельефа, как на карте. Панели и кнопки в форме листа (сильное скругление на двух противоположных углах) с тонкой цветной «прожилкой»; у ползунков бегунок-листик; полностью новый набор двухцветных иконок на плитках-листьях. Двигается только иконка вентилятора, и только когда он крутится. Тачпад и PC-клавиатура в том же стиле.", "Цветовой акцент действует только для «Стекла», «Компактного» и «Неона»; у остальных тем своя палитра.", "В «Авроре», «Сумерках» и «Обсидиане» иконки анимированы. В «Картридже», «Глубине», «Хай-Фай», «Голограмме», «Баухаусе» и «Нефрите» двигается только вентилятор.", "Тачпад и PC-клавиатура подстраиваются под «Аврору», «Сумерки», «Обсидиан», «Картридж», «Глубину», «Хай-Фай», «Голограмму», «Баухаус», «Нефрит» и «Необрутализм». Темы клавиатуры — в Настройки → Клавиатура двух экранов.")),
            "nl" to Entry("Thema's en weergave", "Verandert het hele uiterlijk, niet alleen kleuren.", listOf("Instellingen → Interface → Ontwerp: Levend noorderlicht (standaard), Schemering, Obsidiaan, Cartridge, Diepzee, Hi-Fi-deck, Hologram, Bauhaus, Jade, Glas, Compact, Neon, Zonnewende, Synthwave, Vulkanisch, 8-bit, Neo-brutaal licht en donker.", "Obsidiaan: bijna zwart grafiet met langzaam stromende lijnen, accenten in elektrisch limoen en blauw, eigen geometrische bewegende iconen, grotere onderste knoppen en eigen schuifregelaars.", "Cartridge: retrogaming in een moderne snit. Antraciet consoleplastic met cartridgerood en crèmegoud. Kaarten zijn cartridgebehuizingen met een afgeschuinde hoek, een donkere rand onderaan en labelstrepen; knoppen zijn rubberen consoletoetsen; iconen zijn moderne pixelart; koppen in een monospace consolelettertype. Alleen het ventilatoricoon beweegt, en alleen als de ventilator draait. Profielen blijven bovenaan. Touchpad en pc-toetsenbord in dezelfde stijl.", "Diepzee: donker water, van binnenuit verlicht. Bijna zwart marineblauw met turquoise en violet licht; profielen houden hun eigen heldere kleuren. Kaarten zijn diepe panelen met een zachte gloed in een hoek en een lichtlijn bovenaan, knoppen zijn gladde capsules, iconen zitten in glazen bellen. Alleen het ventilatoricoon beweegt. Touchpad en pc-toetsenbord passen erbij.", "Hi-Fi-deck: een stereo-onderdeel uit de jaren 80. Donker geborsteld metaal met een oranje-rode streepband, amber en turquoise displaylicht. Kaarten zijn frontpanelen met een afschuining, schroefjes en een status-led; knoppen zijn harde toetsen die oplichten; schuifregelaars zijn led-niveaumeters met een mengpaneelfader; de FPS-grafiek is een spectrumanalyser; iconen zitten in kleine displayvensters. Alleen het ventilatoricoon beweegt.", "Hologram: een geprojecteerd head-up display. Cyaan licht op zwart over een vaag zeshoekraster, amber voor accenten. Panelen hebben afgesneden hoeken, knoppen zijn schuine platen, schuifregelaars zijn linialen met een ruitknop, iconen zitten in zeshoeken. Het startscherm is als een cockpit ingedeeld: meetwaarden boven, de profielkeuze onder. Alleen het ventilatoricoon beweegt.", "Bauhaus: gedurfde geometrie. Zwart en gebroken wit met de drie primaire kleuren — geel, rood, blauw. Platte vierkante blokken zonder afronding; gekleurde kaarten met een kwartcirkel en een dikke balk; knoppen zijn vierkante blokken met een zware rand; schuifregelaars zijn een vierkante balk met een rode ronde knop; iconen zijn geometrische tegels. Alleen het ventilatoricoon beweegt.", "Jade: diep bosgroen met jade en lichtgroen licht over vage hoogtelijnen. Panelen en knoppen hebben de vorm van een blad met een dunne kleurnerf; schuifregelaars een bladvormige knop; een volledig nieuwe set tweekleurige iconen op bladtegels. Alleen het ventilatoricoon beweegt, alleen als de ventilator draait.", "Kleuraccent geldt alleen voor Glas, Compact en Neon; de andere ontwerpen hebben een eigen palet.", "Noorderlicht, Schemering en Obsidiaan gebruiken geanimeerde iconen. In Cartridge, Diepzee, Hi-Fi-deck, Hologram, Bauhaus en Jade beweegt alleen de ventilator.", "Touchpad en pc-toetsenbord volgen Noorderlicht, Schemering, Obsidiaan, Cartridge, Diepzee, Hi-Fi-deck, Hologram, Bauhaus, Jade en Neo-brutaal. Toetsenbordthema's staan in Instellingen → Toetsenbord voor twee schermen.")),
            "es" to Entry("Temas y apariencia", "Cambia todo el aspecto, no solo los colores.", listOf("Ajustes → Interfaz → Diseño: Aurora viva (predeterminado), Crepúsculo, Obsidiana, Cartucho, Abismo, Equipo Hi-Fi, Holograma, Bauhaus, Jade, Cristal, Compacto, Neón, Solsticio, Neón retro, Volcánico, 8-bit, Neobrutalista claro y oscuro.", "Obsidiana: grafito casi negro con líneas que fluyen despacio, acentos lima eléctrico y azul, iconos geométricos animados propios, botones inferiores más grandes y deslizadores propios.", "Cartucho: gaming retro con un corte moderno. Plástico de consola gris carbón con rojo cartucho y oro crema. Las tarjetas son carcasas de cartucho con una esquina recortada, un borde oscuro abajo y franjas de etiqueta; los botones son teclas de goma; los iconos son pixel art moderno; los títulos usan una fuente monoespaciada de consola. Solo se mueve el icono del ventilador, y solo mientras gira. Los perfiles siguen arriba. El touchpad y el teclado de PC usan el mismo estilo.", "Abismo: agua oscura iluminada desde dentro. Azul marino casi negro con luz turquesa y violeta; los perfiles mantienen sus colores vivos. Las tarjetas son paneles profundos con un brillo suave en una esquina y una línea de luz arriba, los botones son cápsulas suaves y los iconos están en burbujas de cristal. Solo se mueve el icono del ventilador. El touchpad y el teclado de PC combinan.", "Equipo Hi-Fi: un componente estéreo de los 80. Metal oscuro cepillado con franjas naranja y rojo, luz de pantalla ámbar y turquesa. Las tarjetas son paneles frontales con bisel, tornillos y un LED; los botones son teclas duras que se iluminan; los controles deslizantes son medidores LED con un fader de mesa de mezclas; el gráfico de FPS es un analizador de espectro; los iconos van en pequeñas ventanas de pantalla. Solo se mueve el icono del ventilador.", "Holograma: una pantalla proyectada tipo HUD. Luz cian sobre negro con una retícula hexagonal tenue y ámbar para destacar. Los paneles tienen esquinas cortadas, los botones son placas inclinadas, los controles deslizantes son reglas con un rombo, los iconos van en hexágonos. El panel se organiza como una cabina: lecturas arriba y selector de perfil abajo. Solo se mueve el icono del ventilador.", "Bauhaus: geometría atrevida. Negro y blanco roto con los tres primarios: amarillo, rojo y azul. Bloques cuadrados planos sin redondeo; las tarjetas de color llevan un cuarto de círculo y una barra gruesa; los botones son bloques con borde grueso; los controles deslizantes son una barra cuadrada con un botón rojo redondo; los iconos son baldosas geométricas. Solo se mueve el icono del ventilador.", "Jade: verde bosque profundo con luz jade y lima pálida sobre curvas de nivel tenues. Paneles y botones con forma de hoja y una fina vena de color; los controles deslizantes tienen un botón en forma de hoja; un juego totalmente nuevo de iconos bicolores sobre baldosas de hoja. Solo se mueve el icono del ventilador, y solo cuando gira.", "El acento de color solo aplica a Cristal, Compacto y Neón; los demás diseños traen su propia paleta.", "Aurora, Crepúsculo y Obsidiana usan iconos animados. En Cartucho, Abismo, Equipo Hi-Fi, Holograma, Bauhaus y Jade solo se mueve el ventilador.", "El touchpad y el teclado de PC siguen Aurora, Crepúsculo, Obsidiana, Cartucho, Abismo, Equipo Hi-Fi, Holograma, Bauhaus, Jade y Neobrutalista. Los temas del teclado están en Ajustes → Teclado de doble pantalla.")),
            "de" to Entry("Designs und Darstellung", "Ändert das ganze Aussehen, nicht nur die Farben.", listOf("Einstellungen → Oberfläche → Design: Aurora Live (Standard), Dämmerung, Obsidian, Spielmodul, Tiefsee, Hi-Fi-Anlage, Hologramm, Bauhaus, Jade, Glas, Kompakt, Neon, Sonnenwende, Synthwave, Vulkanisch, 8-Bit, Neo-Brutal hell und dunkel.", "Obsidian: fast schwarzes Graphit mit langsam fließenden Linien, Akzente in elektrischem Limettengrün und Blau, eigene geometrische animierte Symbole, größere untere Tasten und eigene Schieberegler.", "Spielmodul: Retro-Gaming im modernen Schnitt. Anthrazitfarbenes Konsolenplastik mit Modulrot und Cremegold. Karten sind Modulgehäuse mit abgeschrägter Ecke, dunkler Kante unten und Etikettstreifen; Tasten sind Gummi-Konsolentasten; Symbole sind moderne Pixelkunst; Überschriften in einer Monospace-Konsolenschrift. Nur das Lüftersymbol bewegt sich, und nur wenn der Lüfter dreht. Profile bleiben oben. Touchpad und PC-Tastatur im gleichen Stil.", "Tiefsee: dunkles Wasser, von innen beleuchtet. Fast schwarzes Marineblau mit türkisem und violettem Licht; Profile behalten ihre kräftigen Farben. Karten sind tiefe Flächen mit sanftem Leuchten in einer Ecke und einer Lichtlinie oben, Tasten sind glatte Kapseln, Symbole sitzen in Glasblasen. Nur das Lüftersymbol bewegt sich. Touchpad und PC-Tastatur passen dazu.", "Hi-Fi-Anlage: ein Stereogerät der 80er. Dunkles gebürstetes Metall mit orange-roten Streifen, bernsteinfarbenes und türkises Displaylicht. Karten sind Frontplatten mit Fase, Schrauben und Status-LED; Tasten sind harte Knöpfe, die aufleuchten; Schieberegler sind LED-Pegelanzeigen mit Mischpult-Fader; das FPS-Diagramm ist ein Spektrumanalysator; Symbole sitzen in kleinen Displayfenstern. Nur das Lüftersymbol bewegt sich.", "Hologramm: ein projiziertes Head-up-Display. Cyanfarbenes Licht auf Schwarz über einem feinen Sechseckraster, Bernstein für Hervorhebungen. Flächen haben abgeschnittene Ecken, Tasten sind schräge Platten, Schieberegler sind Lineale mit Rautenknopf, Symbole sitzen in Sechsecken. Die Startseite ist wie ein Cockpit angeordnet: Anzeigen oben, Profilwahl unten. Nur das Lüftersymbol bewegt sich.", "Bauhaus: kühne Geometrie. Schwarz und Naturweiß mit den drei Grundfarben Gelb, Rot, Blau. Flache quadratische Blöcke ohne Rundung; farbige Karten mit Viertelkreis und dickem Balken; Tasten sind Blöcke mit kräftigem Rand; Schieberegler sind ein eckiger Balken mit rundem rotem Knopf; Symbole sind geometrische Kacheln. Nur das Lüftersymbol bewegt sich.", "Jade: tiefes Waldgrün mit Jade- und Hellgrün-Licht über feinen Höhenlinien. Flächen und Tasten in Blattform mit einer dünnen Farbader; Schieberegler mit blattförmigem Knopf; ein komplett neuer zweifarbiger Symbolsatz auf Blattkacheln. Nur das Lüftersymbol bewegt sich, und nur wenn er dreht.", "Der Farbakzent gilt nur für Glas, Kompakt und Neon; die anderen Designs haben eine eigene Palette.", "Aurora, Dämmerung und Obsidian nutzen animierte Symbole. In Spielmodul, Tiefsee, Hi-Fi-Anlage, Hologramm, Bauhaus und Jade bewegt sich nur der Lüfter.", "Touchpad und PC-Tastatur folgen Aurora, Dämmerung, Obsidian, Spielmodul, Tiefsee, Hi-Fi-Anlage, Hologramm, Bauhaus, Jade und Neo-Brutal. Tastaturthemen stehen unter Einstellungen → Dual-Screen-Tastatur.")),
            "fr" to Entry("Thèmes et apparence", "Change tout l’aspect, pas seulement les couleurs.", listOf("Réglages → Interface → Design : Aurore vivante (par défaut), Crépuscule, Obsidienne, Cartouche, Abysses, Chaîne hi-fi, Hologramme, Bauhaus, Jade, Verre, Compact, Néon, Solstice, Synthwave, Volcanique, 8-bit, Néo-brutal clair et sombre.", "Obsidienne : graphite presque noir avec des lignes qui coulent lentement, accents vert citron électrique et bleu, icônes géométriques animées propres, boutons du bas plus grands et curseurs propres.", "Plan technique : un dessin industriel la nuit. Encre pâle sur bleu marine profond avec une grille millimétrée fixe. Les cartes sont des feuilles de plan avec des repères d'angle, les boutons sont carrés et plats, les icônes sont des dessins au trait avec axes et cotes. Seule l'icône du ventilateur bouge, et seulement quand il tourne. Le fond et les autres icônes sont fixes, ce qui économise le CPU. Les profils restent en haut. Le pavé tactile et le clavier PC suivent le même style.", "Cartouche : rétro-gaming en version moderne. Plastique de console anthracite, rouge cartouche et or crème. Les cartes sont des coques de cartouche à coin coupé, avec un rebord sombre en bas et des bandes d'étiquette ; les boutons sont des touches en caoutchouc ; les icônes sont du pixel art moderne ; les titres utilisent une police console à chasse fixe. Seule l'icône du ventilateur bouge, et seulement quand il tourne. Les profils restent en haut. Le pavé tactile et le clavier PC suivent le même style.", "Abysses : une eau sombre éclairée de l’intérieur. Bleu marine presque noir avec une lumière turquoise et violette ; les profils gardent leurs couleurs vives. Les cartes sont des panneaux profonds avec une lueur douce dans un coin et un filet de lumière en haut, les boutons sont des capsules lisses, les icônes sont dans des bulles de verre. Seule l’icône du ventilateur bouge. Pavé tactile et clavier PC assortis.", "Chaîne hi-fi : un appareil stéréo des années 80. Métal sombre brossé avec des bandes orange et rouge, lumière d’afficheur ambre et turquoise. Les cartes sont des façades avec chanfrein, vis et voyant LED ; les boutons sont des touches dures qui s’allument ; les curseurs sont des VU-mètres à LED avec un fader de table de mixage ; le graphique FPS est un analyseur de spectre ; les icônes sont dans de petites fenêtres d’afficheur. Seule l’icône du ventilateur bouge.", "Hologramme : un affichage tête haute projeté. Lumière cyan sur noir sur une fine trame d’hexagones, ambre pour les accents. Les panneaux ont des coins coupés, les boutons sont des plaques inclinées, les curseurs sont des règles avec un losange, les icônes sont dans des hexagones. L’accueil est organisé comme un cockpit : mesures en haut, choix du profil en bas. Seule l’icône du ventilateur bouge.", "Bauhaus : une géométrie audacieuse. Noir et blanc cassé avec les trois primaires — jaune, rouge, bleu. Blocs carrés plats sans arrondi ; les cartes colorées portent un quart de cercle et une barre épaisse ; les boutons sont des blocs à bord épais ; les curseurs sont une barre carrée avec un bouton rond rouge ; les icônes sont des tuiles géométriques. Seule l’icône du ventilateur bouge.", "Jade : vert forêt profond avec une lumière jade et vert pâle sur de fines courbes de niveau. Panneaux et boutons en forme de feuille avec une fine nervure colorée ; curseurs avec un bouton en feuille ; un jeu d’icônes bicolores entièrement nouveau sur des tuiles-feuilles. Seule l’icône du ventilateur bouge, et seulement quand il tourne.", "L’accent de couleur ne concerne que Verre, Compact et Néon ; les autres designs ont leur propre palette.", "Aurore, Crépuscule et Obsidienne utilisent des icônes animées. Dans Cartouche, Abysses, Chaîne hi-fi, Hologramme, Bauhaus et Jade, seul le ventilateur bouge.", "Le pavé tactile et le clavier PC suivent Aurore, Crépuscule, Obsidienne, Cartouche, Abysses, Chaîne hi-fi, Hologramme, Bauhaus, Jade et Néo-brutal. Les thèmes du clavier sont dans Réglages → Clavier double écran.")),
            "it" to Entry("Temi e aspetto", "Cambia tutto l’aspetto, non solo i colori.", listOf("Impostazioni → Interfaccia → Design: Aurora viva (predefinito), Crepuscolo, Ossidiana, Cartuccia, Abisso, Impianto hi-fi, Ologramma, Bauhaus, Giada, Vetro, Compatto, Neon, Solstizio, Synthwave, Vulcanico, 8-bit, Neo-brutale chiaro e scuro.", "Ossidiana: grafite quasi nera con linee che scorrono lente, accenti lime elettrico e blu, icone geometriche animate proprie, pulsanti in basso più grandi e cursori propri.", "Cartuccia: retrogaming in chiave moderna. Plastica da console antracite con rosso cartuccia e oro crema. Le schede sono gusci di cartuccia con un angolo tagliato, un bordo scuro in basso e strisce da etichetta; i pulsanti sono tasti in gomma; le icone sono pixel art moderna; i titoli usano un font da console a spaziatura fissa. Si muove solo l'icona della ventola, e solo mentre gira. I profili restano in alto. Touchpad e tastiera PC nello stesso stile.", "Abisso: acqua scura illuminata dall’interno. Blu notte quasi nero con luce turchese e viola; i profili mantengono i loro colori vivaci. Le schede sono pannelli profondi con un bagliore morbido in un angolo e una linea di luce in alto, i pulsanti sono capsule lisce, le icone stanno in bolle di vetro. Si muove solo l’icona della ventola. Touchpad e tastiera PC coordinati.", "Impianto hi-fi: un componente stereo anni ’80. Metallo scuro spazzolato con strisce arancio e rosse, luce di display ambra e turchese. Le schede sono frontalini con smusso, viti e LED; i pulsanti sono tasti rigidi che si illuminano; i cursori sono indicatori di livello a LED con un fader da mixer; il grafico FPS è un analizzatore di spettro; le icone stanno in piccole finestre di display. Si muove solo l’icona della ventola.", "Ologramma: un head-up display proiettato. Luce ciano su nero su una tenue griglia esagonale, ambra per i dettagli. I pannelli hanno angoli tagliati, i pulsanti sono piastre inclinate, i cursori sono righelli con un rombo, le icone stanno in esagoni. La home è organizzata come una cabina: letture in alto, scelta del profilo in basso. Si muove solo l’icona della ventola.", "Bauhaus: geometria audace. Nero e bianco caldo con i tre primari: giallo, rosso, blu. Blocchi quadrati piatti senza arrotondamenti; le schede colorate hanno un quarto di cerchio e una barra spessa; i pulsanti sono blocchi con bordo marcato; i cursori sono una barra quadrata con una manopola rossa rotonda; le icone sono tessere geometriche. Si muove solo l’icona della ventola.", "Giada: verde foresta profondo con luce giada e verde pallido su tenui curve di livello. Pannelli e pulsanti a forma di foglia con una sottile venatura di colore; i cursori hanno una manopola a foglia; un set di icone bicolori completamente nuovo su tessere a foglia. Si muove solo l’icona della ventola, solo quando gira.", "L’accento di colore vale solo per Vetro, Compatto e Neon; gli altri design hanno una propria tavolozza.", "Aurora, Crepuscolo e Ossidiana usano icone animate. In Cartuccia, Abisso, Impianto hi-fi, Ologramma, Bauhaus e Giada si muove solo la ventola.", "Touchpad e tastiera PC seguono Aurora, Crepuscolo, Ossidiana, Cartuccia, Abisso, Impianto hi-fi, Ologramma, Bauhaus, Giada e Neo-brutale. I temi della tastiera sono in Impostazioni → Tastiera a doppio schermo.")),
            "zh" to Entry("主题与外观", "改变整体外观，而不只是颜色。", listOf("设置 → 界面 → 设计：极光（默认）、黄昏、黑曜石、卡带、深海、高保真音响、全息、包豪斯、翡翠、玻璃、紧凑、霓虹、至日、合成波、火山、8 位、新野兽派浅色与深色。", "黑曜石：近黑的石墨底色配缓缓流动的线条，电光青柠与蓝色点缀，专属的几何动态图标、更大的底部按钮和专属滑块。", "卡带：现代风格的复古游戏主题。炭灰色主机塑料配卡带红与奶油金。卡片是切角的卡带外壳，底部有深色边缘和标签条纹；按钮是橡胶主机按键；图标是现代像素画；标题使用等宽主机字体。只有风扇图标会动，且仅在风扇转动时。配置仍在顶部。触控板和 PC 键盘采用同样风格。", "深海：被从内部照亮的深色海水。近乎黑色的深蓝配青绿与紫色光；各配置保留自己的鲜艳颜色。卡片是带角落柔光和顶部光线的深色面板，按钮是圆润胶囊，图标位于玻璃气泡中。只有风扇图标会动。触控板和 PC 键盘风格一致。", "高保真音响：80 年代的立体声设备。深色拉丝金属配橙红条纹，琥珀色与青绿色显示屏光。卡片是带倒角、角落螺丝和状态灯的面板；按钮是会亮起的硬质按键；滑块是带调音台推子的 LED 电平表；FPS 图是频谱分析仪；图标位于小显示窗中。只有风扇图标会动。", "全息：投影式抬头显示。黑底青色光，背景为淡淡的六边形网格，琥珀色用于强调。面板为切角，按钮为倾斜板，滑块为带菱形旋钮的刻度尺，图标位于六边形中。首页像驾驶舱：读数在上，配置选择在下。只有风扇图标会动。", "包豪斯：大胆的几何风格。黑色与暖白配三原色——黄、红、蓝。无圆角的平面方块；彩色卡片带实心四分之一圆和粗条；按钮是粗边方块；滑块是方形条配红色圆形旋钮；图标是几何方块。只有风扇图标会动。", "翡翠：深邃的森林绿，配翡翠绿和浅青柠光，背景有淡淡的等高线。面板和按钮呈叶片形并带细细的彩色叶脉；滑块旋钮为叶片形；全新的双色图标置于叶片方块上。只有风扇图标会动，且仅在风扇转动时。", "颜色强调仅适用于玻璃、紧凑和霓虹；其他设计自带配色。", "极光、黄昏和黑曜石使用动态图标。卡带、深海、高保真音响、全息、包豪斯和翡翠中只有风扇图标会动。", "触控板和 PC 键盘跟随极光、黄昏、黑曜石、卡带、深海、高保真音响、全息、包豪斯、翡翠和新野兽派。键盘主题在 设置 → 双屏键盘。"))
        )),
        Topic("settings", "cpu", mapOf(
            "en" to Entry("Settings & AYANEO button", "Sections: Interface, Button & components, Audio, Dual-screen keyboard, About.", listOf("The AYANEO button always belongs to PocketHub: each press shows or hides it. Its accessibility service is core functionality, so there is no switch for it any more.", "Setup wizard on first launch: language, welcome, AYANEO Home / AYASpace and start after boot, sound (volume per screen, volume buttons, where the panel appears), keyboard (where it opens, languages; small keys and the Cartridge theme are set). Run it again from Settings → About → Run setup again.", "Button & components also has AYANEO Home / AYASpace switches, start after boot and “Hide PocketHub from Recent apps” (on by default, so it can't be swiped away).", "Button remapping, charging fan, Wi-Fi sleep, external monitor and memory are on page 2 → Device; controller mode is on page 2 → Controller.", "After a reboot the last profile, fan mode, overheat protection, swap and equalizer come back automatically.")),
            "ru" to Entry("Настройки и кнопка AYANEO", "Разделы: «Интерфейс», «Кнопка и компоненты», «Звук», «Двойная клавиатура», «О программе».", listOf("Кнопка AYANEO всегда принадлежит PocketHub: каждое нажатие показывает или скрывает его. Его служба специальных возможностей — базовая функция, поэтому переключателя для неё больше нет.", "При первом запуске — мастер настройки: язык, приветствие, AYANEO Home / AYASpace и запуск при загрузке, звук (громкость по экранам, кнопки громкости, где показывать панель), клавиатура (где открывать, языки; ставятся маленькие клавиши и тема «Картридж»). Пройти заново: Настройки → «О программе» → «Пройти начальную настройку заново».", "В «Кнопке и компонентах» также есть переключатели AYANEO Home / AYASpace, запуск после загрузки и «Скрыть PocketHub из последних приложений» (включено по умолчанию, чтобы его нельзя было смахнуть).", "Переназначение кнопок, вентилятор при зарядке, Wi-Fi во сне, внешний монитор и память — на странице 2 → «Устройство»; режим контроллера — на странице 2 → «Контроллер».", "После перезагрузки последний профиль, режим вентилятора, защита от перегрева, swap и эквалайзер восстанавливаются автоматически.")),
            "nl" to Entry("Instellingen en AYANEO-knop", "Secties: Interface, Knop en onderdelen, Geluid, Toetsenbord voor twee schermen, Over.", listOf("De AYANEO-knop hoort altijd bij PocketHub: elke druk toont of verbergt het. De toegankelijkheidsservice is basisfunctionaliteit, daarom is er geen schakelaar meer.", "Installatiewizard bij de eerste start: taal, welkom, AYANEO Home / AYASpace en starten na opstarten, geluid (volume per scherm, volumeknoppen, waar het paneel verschijnt), toetsenbord (waar het opent, talen; kleine toetsen en het Cartridge-thema worden ingesteld). Opnieuw via Instellingen → Over → Installatie opnieuw doen.", "Knop en onderdelen heeft ook AYANEO Home / AYASpace-schakelaars, starten na opstarten en “PocketHub verbergen uit recente apps” (standaard aan, zodat het niet weggeveegd kan worden).", "Knoppen toewijzen, oplaadventilator, wifi-slaap, externe monitor en geheugen staan op pagina 2 → Apparaat; de controllermodus op pagina 2 → Controller.", "Na een herstart komen het laatste profiel, de ventilatormodus, oververhittingsbeveiliging, swap en equalizer vanzelf terug.")),
            "es" to Entry("Ajustes y botón AYANEO", "Secciones: Interfaz, Botón y componentes, Audio, Teclado de doble pantalla, Acerca de.", listOf("El botón AYANEO siempre pertenece a PocketHub: cada pulsación lo muestra u oculta. Su servicio de accesibilidad es una función básica, así que ya no hay interruptor.", "Asistente de configuración en el primer inicio: idioma, bienvenida, AYANEO Home / AYASpace e inicio al arrancar, sonido (volumen por pantalla, botones de volumen, dónde aparece el panel), teclado (dónde se abre, idiomas; se ponen teclas pequeñas y el tema Cartucho). Repítelo en Ajustes → Acerca de → Repetir la configuración.", "Botón y componentes también tiene interruptores de AYANEO Home / AYASpace, inicio tras arrancar y “Ocultar PocketHub de apps recientes” (activado por defecto, para que no se pueda descartar).", "Reasignar botones, ventilador al cargar, wifi en reposo, monitor externo y memoria están en la página 2 → Dispositivo; el modo del mando en la página 2 → Mando.", "Tras reiniciar vuelven automáticamente el último perfil, el modo de ventilador, la protección contra sobrecalentamiento, el swap y el ecualizador.")),
            "de" to Entry("Einstellungen und AYANEO-Taste", "Bereiche: Oberfläche, Taste und Komponenten, Ton, Zwei-Bildschirm-Tastatur, Info.", listOf("Die AYANEO-Taste gehört immer PocketHub: jeder Druck blendet es ein oder aus. Der Bedienungshilfedienst ist Grundfunktion, daher gibt es keinen Schalter mehr.", "Einrichtungsassistent beim ersten Start: Sprache, Willkommen, AYANEO Home / AYASpace und Start nach dem Booten, Ton (Lautstärke pro Bildschirm, Lautstärketasten, wo das Feld erscheint), Tastatur (wo sie öffnet, Sprachen; kleine Tasten und das Spielmodul-Design werden gesetzt). Erneut über Einstellungen → Info → Einrichtung wiederholen.", "Taste und Komponenten enthält außerdem Schalter für AYANEO Home / AYASpace, Start nach dem Booten und „PocketHub in letzten Apps ausblenden“ (standardmäßig an, damit es nicht weggewischt werden kann).", "Tastenbelegung, Lüfter beim Laden, WLAN im Ruhezustand, externer Monitor und Speicher sind auf Seite 2 → Gerät; der Controllermodus auf Seite 2 → Controller.", "Nach einem Neustart kehren letztes Profil, Lüftermodus, Überhitzungsschutz, Swap und Equalizer automatisch zurück.")),
            "fr" to Entry("Réglages et bouton AYANEO", "Sections : Interface, Bouton et composants, Audio, Clavier double écran, À propos.", listOf("Le bouton AYANEO appartient toujours à PocketHub : chaque appui l’affiche ou le masque. Son service d’accessibilité est une fonction de base, il n’y a donc plus d’interrupteur.", "Assistant de configuration au premier lancement : langue, bienvenue, AYANEO Home / AYASpace et démarrage au boot, son (volume par écran, boutons de volume, où apparaît le panneau), clavier (où il s’ouvre, langues ; petites touches et thème Cartouche appliqués). À relancer via Réglages → À propos → Refaire la configuration.", "Bouton et composants contient aussi les interrupteurs AYANEO Home / AYASpace, le démarrage au boot et « Masquer PocketHub des apps récentes » (activé par défaut, pour qu’il ne puisse pas être balayé).", "La réaffectation des boutons, le ventilateur en charge, le Wi-Fi en veille, le moniteur externe et la mémoire sont sur la page 2 → Appareil ; le mode de la manette sur la page 2 → Manette.", "Après un redémarrage, le dernier profil, le mode du ventilateur, la protection contre la surchauffe, le swap et l’égaliseur reviennent automatiquement.")),
            "it" to Entry("Impostazioni e pulsante AYANEO", "Sezioni: Interfaccia, Pulsante e componenti, Audio, Tastiera doppio schermo, Info.", listOf("Il pulsante AYANEO appartiene sempre a PocketHub: ogni pressione lo mostra o nasconde. Il suo servizio di accessibilità è una funzione di base, quindi non c’è più un interruttore.", "Configurazione guidata al primo avvio: lingua, benvenuto, AYANEO Home / AYASpace e avvio al boot, audio (volume per schermo, tasti volume, dove appare il pannello), tastiera (dove si apre, lingue; vengono impostati tasti piccoli e il tema Cartuccia). Ripetila da Impostazioni → Info → Ripeti la configurazione.", "Pulsante e componenti ha anche gli interruttori AYANEO Home / AYASpace, l’avvio al boot e “Nascondi PocketHub dalle app recenti” (attivo di default, così non si può scorrere via).", "Rimappatura pulsanti, ventola in ricarica, Wi-Fi a riposo, monitor esterno e memoria sono nella pagina 2 → Dispositivo; la modalità controller nella pagina 2 → Controller.", "Dopo un riavvio tornano automaticamente l’ultimo profilo, la modalità ventola, la protezione dal surriscaldamento, lo swap e l’equalizzatore.")),
            "zh" to Entry("设置与 AYANEO 键", "分区：界面、按键与组件、声音、双屏键盘、关于。", listOf("AYANEO 键始终归 PocketHub 使用：每次按下都会显示或隐藏它。其无障碍服务是基础功能，因此不再提供开关。", "首次启动时的设置向导：语言、欢迎、AYANEO Home / AYASpace 与开机启动、声音（分屏音量、音量键、面板显示位置）、键盘（在哪里打开、语言；会设为小按键和“卡带”主题）。可在 设置 → 关于 → 重新设置 中再次运行。", "“按键与组件”中还有 AYANEO Home / AYASpace 开关、开机启动，以及“从最近应用中隐藏 PocketHub”（默认开启，无法被划掉）。", "按键映射、充电时风扇、息屏 Wi-Fi、外接显示器和内存位于第 2 页 → 设备；手柄模式位于第 2 页 → 手柄。", "重启后会自动恢复上次的配置、风扇模式、过热保护、swap 和均衡器。"))
        )),
        Topic("root", "cpu", mapOf(
            "en" to Entry("Root access", "PocketHub needs root for almost everything.", listOf("On start PocketHub asks for root; Magisk should show its prompt. Without root a red “No root access” card appears on the dashboard.", "If Magisk doesn't ask: open Magisk → Superuser and turn PocketHub on, and check that Automatic response is set to Prompt.", "“Ask again” repeats the request; “Open Magisk” goes straight there.", "Button remapping and the volume panel work without root; profiles, fan, Turbo, input, sound control and screenshots do not.")),
            "ru" to Entry("Root-доступ", "Почти всему в PocketHub нужен root.", listOf("При запуске PocketHub запрашивает root; Magisk должен показать окно. Без root на главной появляется красная карточка «Нет root-доступа».", "Если Magisk не спрашивает: открой Magisk → Суперпользователь и включи PocketHub, проверь, что «Автоматический ответ» стоит на «Запрос».", "«Запросить снова» повторяет запрос; «Открыть Magisk» сразу переходит туда.", "Переназначение кнопок и панель громкости работают без root; профили, вентилятор, Турбо, ввод, звук и снимки экрана — нет.")),
            "nl" to Entry("Roottoegang", "PocketHub heeft root nodig voor bijna alles.", listOf("Bij het starten vraagt PocketHub om root; Magisk hoort een venster te tonen. Zonder root verschijnt een rode kaart “Geen roottoegang”.", "Vraagt Magisk niets: open Magisk → Superuser, zet PocketHub aan en controleer dat Automatisch antwoord op Vragen staat.", "“Opnieuw vragen” herhaalt het verzoek; “Magisk openen” gaat er direct heen.", "Knoppen toewijzen en het volumepaneel werken zonder root; profielen, ventilator, Turbo, invoer, geluid en schermafbeeldingen niet.")),
            "es" to Entry("Acceso root", "PocketHub necesita root para casi todo.", listOf("Al iniciar, PocketHub pide root; Magisk debería mostrar su ventana. Sin root aparece una tarjeta roja “Sin acceso root”.", "Si Magisk no pregunta: abre Magisk → Superusuario, activa PocketHub y comprueba que Respuesta automática sea Preguntar.", "“Pedir de nuevo” repite la solicitud; “Abrir Magisk” va directo.", "Reasignar botones y el panel de volumen funcionan sin root; perfiles, ventilador, Turbo, entrada, sonido y capturas no.")),
            "de" to Entry("Root-Zugriff", "PocketHub braucht für fast alles Root.", listOf("Beim Start fragt PocketHub nach Root; Magisk sollte ein Fenster zeigen. Ohne Root erscheint eine rote Karte „Kein Root-Zugriff“.", "Fragt Magisk nicht: Magisk → Superuser öffnen, PocketHub einschalten und prüfen, dass die automatische Antwort auf Fragen steht.", "„Erneut fragen“ wiederholt die Anfrage; „Magisk öffnen“ geht direkt dorthin.", "Tastenbelegung und Lautstärkefeld funktionieren ohne Root; Profile, Lüfter, Turbo, Eingabe, Ton und Screenshots nicht.")),
            "fr" to Entry("Accès root", "PocketHub a besoin de root pour presque tout.", listOf("Au démarrage, PocketHub demande root ; Magisk doit afficher sa fenêtre. Sans root, une carte rouge « Pas d'accès root » apparaît.", "Si Magisk ne demande rien : ouvrez Magisk → Superutilisateur, activez PocketHub et vérifiez que Réponse automatique est sur Demander.", "« Redemander » relance la demande ; « Ouvrir Magisk » y mène directement.", "La réassignation des boutons et le panneau de volume marchent sans root ; profils, ventilateur, Turbo, saisie, son et captures non.")),
            "it" to Entry("Accesso root", "PocketHub ha bisogno di root per quasi tutto.", listOf("All'avvio PocketHub chiede root; Magisk dovrebbe mostrare la sua finestra. Senza root compare una scheda rossa “Nessun accesso root”.", "Se Magisk non chiede: apri Magisk → Superuser, attiva PocketHub e verifica che Risposta automatica sia su Chiedi.", "“Chiedi di nuovo” ripete la richiesta; “Apri Magisk” porta lì direttamente.", "Riassegnazione tasti e pannello volume funzionano senza root; profili, ventola, Turbo, input, audio e screenshot no.")),
            "zh" to Entry("Root 权限", "PocketHub 几乎所有功能都需要 root。", listOf("启动时 PocketHub 会请求 root，Magisk 应弹出授权窗口。没有 root 时，仪表盘上会出现红色的“没有 root 权限”卡片。", "如果 Magisk 没有询问：打开 Magisk → 超级用户，开启 PocketHub，并确认“自动响应”设为“提示”。", "“重新请求”会再次申请；“打开 Magisk”直接跳转。", "按键映射和音量面板无需 root；配置、风扇、Turbo、输入、声音和截图则需要。"))
        ))
    )
}
